'use client'
import React from 'react'

import type { ClipboardPasteEligibilityArgs } from '../ClipboardAction/types.js'

import { ArrowIcon } from '../../icons/Arrow/index.js'
import { CopyIcon } from '../../icons/Copy/index.js'
import { DuplicateIcon } from '../../icons/Duplicate/index.js'
import { MoreIcon } from '../../icons/More/index.js'
import { PlusIcon } from '../../icons/Plus/index.js'
import { SwapIcon } from '../../icons/Swap/index.js'
import { XIcon } from '../../icons/X/index.js'
import { useTranslation } from '../../providers/Translation/index.js'
import { useCanPasteClipboard } from '../ClipboardAction/useCanPasteClipboard.js'
import { Popup, PopupList } from '../Popup/index.js'
import './index.css'

const baseClass = 'array-actions'

export type Props = {
  addRow: (current: number, blockType?: string) => Promise<void> | void
  copyRow: (index: number) => void
  duplicateRow: (current: number) => void
  hasMaxRows: boolean
  index: number
  isSortable?: boolean
  label: string
  moveRow: (from: number, to: number) => void
  pasteData: ClipboardPasteEligibilityArgs
  pasteRow: (index: number) => void
  pasteRowBelow: (index: number) => void
  removeRow: (index: number) => void
  rowCount: number
}

export const ArrayAction: React.FC<Props> = ({
  addRow,
  copyRow,
  duplicateRow,
  hasMaxRows,
  index,
  isSortable,
  label,
  moveRow,
  pasteData,
  pasteRow,
  pasteRowBelow,
  removeRow,
  rowCount,
}) => {
  const { t } = useTranslation()

  const { canPaste, refresh } = useCanPasteClipboard(pasteData)

  return (
    <Popup
      button={<MoreIcon />}
      buttonAriaLabel={`${t('general:moreOptions')}: ${label}`}
      buttonClassName={`${baseClass}__button`}
      caret={false}
      className={baseClass}
      horizontalAlign="right"
      onToggleOpen={(active) => {
        if (active) {
          refresh()
        }
      }}
      popupType="menu"
      render={({ close }) => {
        return (
          <PopupList.MenuItem>
            {isSortable && index !== 0 && (
              <PopupList.Button
                className={`${baseClass}__action ${baseClass}__move-up`}
                icon={<ArrowIcon direction="up" size={24} />}
                onClick={() => {
                  moveRow(index, index - 1)
                  close()
                }}
              >
                {t('general:moveUp')}
              </PopupList.Button>
            )}
            {isSortable && index < rowCount - 1 && (
              <PopupList.Button
                className={`${baseClass}__action`}
                icon={<ArrowIcon direction="down" size={24} />}
                onClick={() => {
                  moveRow(index, index + 1)
                  close()
                }}
              >
                {t('general:moveDown')}
              </PopupList.Button>
            )}
            {!hasMaxRows && (
              <React.Fragment>
                <PopupList.Button
                  className={`${baseClass}__action ${baseClass}__add`}
                  icon={<PlusIcon size={24} />}
                  onClick={() => {
                    void addRow(index + 1)
                    close()
                  }}
                >
                  {t('general:addBelow')}
                </PopupList.Button>
                <PopupList.Button
                  className={`${baseClass}__action ${baseClass}__duplicate`}
                  icon={<DuplicateIcon size={24} />}
                  onClick={() => {
                    duplicateRow(index)
                    close()
                  }}
                >
                  {t('general:duplicate')}
                </PopupList.Button>
              </React.Fragment>
            )}
            <PopupList.Button
              className={`${baseClass}__action ${baseClass}__copy`}
              icon={<CopyIcon size={24} />}
              onClick={() => {
                copyRow(index)
                close()
              }}
            >
              {t('general:copyRow')}
            </PopupList.Button>
            {!hasMaxRows && (
              <PopupList.Button
                className={`${baseClass}__action ${baseClass}__paste-below`}
                disabled={!canPaste}
                icon={<ArrowIcon direction="down" size={24} />}
                onClick={() => {
                  pasteRowBelow(index)
                  close()
                }}
              >
                {t('general:pasteBelow')}
              </PopupList.Button>
            )}
            <PopupList.Button
              className={`${baseClass}__action ${baseClass}__paste`}
              disabled={!canPaste}
              icon={<SwapIcon />}
              onClick={() => {
                pasteRow(index)
                close()
              }}
            >
              {t('general:replaceRow')}
            </PopupList.Button>
            <PopupList.Button
              className={`${baseClass}__action ${baseClass}__remove`}
              icon={<XIcon size={24} />}
              onClick={() => {
                removeRow(index)
                close()
              }}
            >
              {t('general:remove')}
            </PopupList.Button>
          </PopupList.MenuItem>
        )
      }}
    />
  )
}

elements/Autosave/index.tsx:
'use client'
import type { ClientCollectionConfig, ClientGlobalConfig } from 'payload'

import { dequal } from 'dequal/lite'
import {
  formatAdminURL,
  getAutosaveInterval,
  hasDraftValidationEnabled,
  reduceFieldsToValues,
} from 'payload/shared'
import * as qs from 'qs-esm'
import React, { useDeferredValue, useEffect, useRef, useState } from 'react'

import type { OnSaveContext } from '../../views/Edit/index.js'

import {
  useAllFormFields,
  useForm,
  useFormModified,
  useFormSubmitted,
} from '../../forms/Form/context.js'
import { useDebounce } from '../../hooks/useDebounce.js'
import { useEffectEvent } from '../../hooks/useEffectEvent.js'
import { useQueue } from '../../hooks/useQueue.js'
import { useConfig } from '../../providers/Config/index.js'
import { useDocumentInfo } from '../../providers/DocumentInfo/index.js'
import { useLocale } from '../../providers/Locale/index.js'
import { useTranslation } from '../../providers/Translation/index.js'
import { useUploadEdits } from '../../providers/UploadEdits/index.js'
import { reduceFieldsToValuesWithValidation } from '../../utilities/reduceFieldsToValuesWithValidation.js'
import { LeaveWithoutSaving } from '../LeaveWithoutSaving/index.js'
import './index.css'

const baseClass = 'autosave'
// The minimum time the saving state should be shown
const minimumAnimationTime = 1000

export type Props = {
  collection?: ClientCollectionConfig
  global?: ClientGlobalConfig
  id?: number | string
  publishedDocUpdatedAt: string
}

export const Autosave: React.FC<Props> = ({ id, collection, global: globalDoc }) => {
  const {
    config: {
      routes: { api },
    },
  } = useConfig()

  const {
    docConfig,
    mostRecentVersionIsAutosaved,
    setMostRecentVersionIsAutosaved,
    setUnpublishedVersionCount,
  } = useDocumentInfo()

  const { isValid, setBackgroundProcessing, submit } = useForm()

  const [formState] = useAllFormFields()
  const modified = useFormModified()
  const submitted = useFormSubmitted()

  const currentLocale = useLocale()
  const locale = currentLocale?.code
  const { t } = useTranslation()
  const { uploadEdits } = useUploadEdits()

  const interval = getAutosaveInterval(docConfig)
  const validateOnDraft = hasDraftValidationEnabled(docConfig)

  const [_saving, setSaving] = useState(false)

  const saving = useDeferredValue(_saving)

  const debouncedFormState = useDebounce(formState, interval)

  const { queueTask } = useQueue()

  const autosaveTimeoutRef = useRef<NodeJS.Timeout | null>(null)

  const handleAutosave = useEffectEvent(() => {
    autosaveTimeoutRef.current = undefined
    // We need to log the time in order to figure out if we need to trigger the state off later
    let startTimestamp = undefined
    let endTimestamp = undefined

    const hideIndicator = () => {
      // If request was faster than minimum animation time, animate the difference
      if (endTimestamp - startTimestamp < minimumAnimationTime) {
        autosaveTimeoutRef.current = setTimeout(
          () => {
            setSaving(false)
          },
          minimumAnimationTime - (endTimestamp - startTimestamp),
        )
      } else {
        stopAutoSaveIndicator()
      }
    }

    queueTask(
      async () => {
        if (modified) {
          startTimestamp = new Date().getTime()

          setSaving(true)

          let url: string
          let method: string
          let entitySlug: string
          const params = qs.stringify(
            {
              autosave: true,
              depth: 0,
              draft: true,
              'fallback-locale': 'null',
              locale,
              uploadEdits: uploadEdits || undefined,
            },
            {
              addQueryPrefix: true,
            },
          )

          if (collection && id) {
            entitySlug = collection.slug
            url = formatAdminURL({
              apiRoute: api,
              path: `/${entitySlug}/${id}${params}`,
            })
            method = 'PATCH'
          }

          if (globalDoc) {
            entitySlug = globalDoc.slug
            url = formatAdminURL({
              apiRoute: api,
              path: `/globals/${entitySlug}${params}`,
            })
            method = 'POST'
          }

          const { valid } = reduceFieldsToValuesWithValidation(formState, true)

          const skipSubmission = submitted && !valid && validateOnDraft

          if (!skipSubmission && modified && url) {
            const result = await submit<any, OnSaveContext>({
              acceptValues: {
                overrideLocalChanges: false,
              },
              action: url,
              context: {
                getDocPermissions: false,
                incrementVersionCount: !mostRecentVersionIsAutosaved,
              },
              disableFormWhileProcessing: false,
              disableSuccessStatus: true,
              method,
              overrides: {
                _status: 'draft',
              },
              skipValidation: !validateOnDraft,
            })

            if (result && result?.res?.ok && !mostRecentVersionIsAutosaved) {
              setMostRecentVersionIsAutosaved(true)
              setUnpublishedVersionCount((prev) => prev + 1)
            }

            const newDate = new Date()

            // We need to log the time in order to figure out if we need to trigger the state off later
            endTimestamp = newDate.getTime()

            hideIndicator()
          }
        }
      },
      {
        afterProcess: () => {
          setBackgroundProcessing(false)
        },
        beforeProcess: () => {
          setBackgroundProcessing(true)
        },
      },
    )
  })

  const didMount = useRef(false)
  const previousDebouncedData = useRef(reduceFieldsToValues(debouncedFormState))
  const previousUploadEdits = useRef(uploadEdits)

  // When debounced fields change, autosave
  useEffect(() => {
    /**
     * Ensure autosave doesn't run on mount
     */
    if (!didMount.current) {
      didMount.current = true
      return
    }

    /**
     * Ensure autosave only runs if the form data changes, not every time the entire form state changes
     * Remove `updatedAt` from comparison as it changes on every autosave interval.
     */
    const { updatedAt: _, ...formData } = reduceFieldsToValues(debouncedFormState)
    const { updatedAt: __, ...prevFormData } = previousDebouncedData.current

    if (dequal(formData, prevFormData) && dequal(uploadEdits, previousUploadEdits.current)) {
      return
    }

    previousDebouncedData.current = formData
    previousUploadEdits.current = uploadEdits

    handleAutosave()
  }, [debouncedFormState, uploadEdits])

  /**
   * If component unmounts, clear the autosave timeout
   */
  useEffect(() => {
    return () => {
      stopAutoSaveIndicator()
    }
  }, [])

  const stopAutoSaveIndicator = useEffectEvent(() => {
    if (autosaveTimeoutRef.current) {
      clearTimeout(autosaveTimeoutRef.current)
    }

    setSaving(false)
  })

  return (
    <React.Fragment>
      {validateOnDraft && !isValid && <LeaveWithoutSaving />}
      {saving && <div className={baseClass}>{t('general:saving')}</div>}
    </React.Fragment>
  )
}

