@layer payload-default {
  .bulk-upload--file-manager__header-title-section {
    display: flex;
    gap: var(--spacer-2);
    align-items: center;
  }

  .bulk-upload--file-manager .dialog__header-extras {
    display: flex;
    gap: var(--spacer-2);
  }

  /* The dialog is otherwise content-sized; give it a definite height so the inner flex chain has
     something to resolve against and the fields column can scroll internally. */
  .dialog.bulk-upload--file-manager {
    height: min(720px, var(--dialog-max-height));
  }

  /* The body is the two-column row (file tree + edit view) that fills the space between the header
     and the actions footer. */
  .bulk-upload--file-manager__body {
    display: flex;
    flex: 1 1 auto;
    min-height: 0;
    width: 100%;
    overflow: hidden;
  }

  .bulk-upload--file-manager__editView {
    display: flex;
    flex-direction: column;
    /* Edit view holds the 4fr content + 5fr media columns, so it takes 9fr next to the 3fr tree. */
    flex: 9 1 0;
    min-width: 0;
    height: 100%;
    max-height: 100%;
    /* The edit view itself does not scroll — the preview stays put while the fields column scrolls
       internally. */
    overflow: hidden;
  }

  .bulk-upload--file-manager .collection-edit__form {
    flex: 1;
    min-height: 0;
  }

  /* Desktop: fields sit on the left and the preview on the right as a fixed-width side panel,
     separated by a divider. The shared layout has no base flex rules of its own, so the row,
     ordering and sizing are established here. The responsive stacking is handled by the viewport
     media query below (the bulk modal does not establish the `edit-main` container query the
     document edit page relies on). */
  .bulk-upload--file-manager .collection-edit__upload-layout {
    display: flex;
    flex-direction: row;
    height: 100%;
    align-items: stretch;
  }

  /* The fields scroll within their own column so the preview stays in place. */
  .bulk-upload--file-manager .collection-edit__upload-layout .document-fields {
    order: 0;
    flex: 4 1 0;
    min-width: 0;
    min-height: 0;
    height: 100%;
    overflow-y: auto;
  }

  /* The preview sits on the right (5fr media : 4fr content) with a divider. */
  .bulk-upload--file-manager .collection-edit__upload-layout .file-manager {
    order: 1;
    flex: 5 1 0;
    min-height: 0;
    border-inline-start: var(--stroke-width-small) solid var(--color-border);
  }

  /* Contained file manager (not the full-viewport sticky panel used on the document edit page);
     the preview fills its column and bleeds to the edges. */
  .bulk-upload--file-manager .file-manager {
    min-height: 0;
    border: none;
  }

  .bulk-upload--file-manager .file-manager__panel {
    position: static;
    height: 100%;
    min-height: 0;
  }

  .bulk-upload--file-manager .file-manager__upload {
    padding: 0;
    justify-content: flex-start;
  }

  /* The preview panel bleeds to the edges, but the media itself is inset so it has breathing room. */
  .bulk-upload--file-manager .file-manager__selected-preview {
    max-width: none;
    width: 100%;
    flex: 1;
    height: auto;
    min-height: 0;
    padding: var(--gutter-h);
    border-radius: 0;
  }

  /* Align the file name input with the document fields (same horizontal gutter), so they line up
     when stacked. */
  .bulk-upload--file-manager .file-manager__file-adjustments {
    padding-inline: var(--gutter-h);
  }

  /* Stack on mobile — the modal is full-screen and there is no room for two columns. The whole
     edit view scrolls as one column (no divider, no internal field scroll). */
  /* stylelint-disable-next-line plugin/no-max-width-media-query -- TODO: pre-existing; migrate to a mobile-first min-width query */
  @media (max-width: 1024px) {
    .bulk-upload--file-manager__body {
      flex-direction: column-reverse;
    }

    .bulk-upload--file-manager__editView {
      overflow-x: hidden;
      overflow-y: auto;
    }

    .bulk-upload--file-manager .collection-edit__upload-layout {
      flex-direction: column;
      height: auto;
    }

    .bulk-upload--file-manager .collection-edit__upload-layout .file-manager {
      order: 0;
      border-inline-start: 0;
      /* Size to content in the stacked column. The desktop fill chain uses flex-basis: 0, which
         collapses to 0 height here (auto-height column) and lets the preview overflow the fields. */
      flex: 0 0 auto;
    }

    .bulk-upload--file-manager .file-manager__content {
      flex: 0 0 auto;
    }

    .bulk-upload--file-manager .file-manager__panel {
      height: auto;
    }

    /* Stack the preview above the file name and size to content. The base layout uses
       `flex: 1 0 0`, which caps the upload at the column's available height and lets the file name
       overflow out the bottom; `flex: 0 0 auto` lets it grow to contain both. The min-height keeps
       the (absolutely positioned) empty-state dropzone room when no preview is present. */
    .bulk-upload--file-manager .file-manager__upload {
      flex: 0 0 auto;
      min-height: min(50dvh, 360px);
    }

    .bulk-upload--file-manager .file-manager__selected-preview {
      flex: none;
      height: min(50dvh, 360px);
    }

    .bulk-upload--file-manager .collection-edit__upload-layout .document-fields {
      /* Reset the desktop flex-basis: 0 fill so the fields size to their content in the auto-height
         stacked column instead of collapsing to zero height. */
      flex: 0 0 auto;
      height: auto;
      overflow-y: visible;
    }
  }

  /* stylelint-disable-next-line plugin/no-max-width-media-query -- TODO: pre-existing; migrate to a mobile-first min-width query */
  @media (max-width: 768px) {
    .bulk-upload--file-manager .document-fields__edit {
      padding-top: var(--spacer-3);
    }
  }
}

'use client'

import { useModal } from '@faceless-ui/modal'
import { reduceFieldsToValues } from 'payload/shared'
import React from 'react'

import { PlusIcon } from '../../../icons/Plus/index.js'
import { useAuth } from '../../../providers/Auth/index.js'
import { useConfig } from '../../../providers/Config/index.js'
import { DocumentInfoProvider } from '../../../providers/DocumentInfo/index.js'
import { useTranslation } from '../../../providers/Translation/index.js'
import { Button } from '../../Button/index.js'
import { DialogHeader } from '../../Dialog/DialogHeader/index.js'
import { DialogModal } from '../../Dialog/DialogModal/index.js'
import { DialogTitle } from '../../Dialog/DialogTitle/index.js'
import { ErrorPill } from '../../ErrorPill/index.js'
import { ActionsBar } from '../ActionsBar/index.js'
import { AddFilesView } from '../AddFilesView/index.js'
import { discardBulkUploadModalSlug, DiscardWithoutSaving } from '../DiscardWithoutSaving/index.js'
import { EditForm } from '../EditForm/index.js'
import { EditManyBulkUploads } from '../EditMany/index.js'
import { FileSidebar } from '../FileSidebar/index.js'
import { useFormsManager } from '../FormsManager/index.js'
import { useBulkUpload } from '../index.js'
import './index.css'

const baseClass = 'bulk-upload--file-manager'

const addMoreFilesModalSlug = 'bulk-upload-modal--add-more-files'

type Props = {
  readonly modalSlug: string
}

export function AddingFilesView({ modalSlug }: Props) {
  const {
    activeIndex,
    addFiles,
    collectionSlug,
    docPermissions,
    documentSlots,
    forms,
    hasPublishPermission,
    hasSavePermission,
    hasSubmitted,
    isInitializing,
    resetUploadEdits,
    totalErrorCount,
    updateUploadEdits,
  } = useFormsManager()
  const { initialFiles, initialForms, maxFiles } = useBulkUpload()
  const activeForm = forms[activeIndex]
  const { getEntityConfig } = useConfig()
  const { i18n, t } = useTranslation()
  const { user } = useAuth()
  const { closeModal, openModal } = useModal()

  const handleAddFiles = React.useCallback(
    (filelist: FileList) => {
      void addFiles(filelist).then((didAddFiles) => {
        if (didAddFiles) {
          closeModal(addMoreFilesModalSlug)
        }
      })
    },
    [addFiles, closeModal],
  )

  const totalFileCount = isInitializing
    ? (initialFiles?.length ?? initialForms?.length)
    : forms.length
  const canAddMoreFiles = typeof maxFiles === 'number' ? totalFileCount < maxFiles : true

  const collectionConfig = getEntityConfig({ collectionSlug })

  return (
    <>
      <DialogModal className={baseClass} size="large" slug={modalSlug}>
        <DialogHeader
          onClose={() => openModal(discardBulkUploadModalSlug)}
          showClose={true}
          title={
            <div className={`${baseClass}__header-title-section`}>
              <DialogTitle title={t('upload:bulkUpload')} />
              {totalErrorCount > 0 && <ErrorPill count={totalErrorCount} i18n={i18n} withMessage />}
            </div>
          }
        >
          {canAddMoreFiles && !isInitializing ? (
            <Button
              buttonStyle="secondary"
              icon={<PlusIcon size={24} />}
              iconPosition="left"
              onClick={() => openModal(addMoreFilesModalSlug)}
            >
              {t('upload:addFiles')}
            </Button>
          ) : null}

          <EditManyBulkUploads collection={collectionConfig} />
        </DialogHeader>

        <div className={`${baseClass}__body`}>
          <FileSidebar />

          <div className={`${baseClass}__editView`}>
            {activeForm && !isInitializing ? (
              <DocumentInfoProvider
                collectionSlug={collectionSlug}
                currentEditor={user}
                docPermissions={docPermissions}
                hasPublishedDoc={false}
                hasPublishPermission={hasPublishPermission}
                hasSavePermission={hasSavePermission}
                id={null}
                initialData={reduceFieldsToValues(activeForm.formState, true)}
                initialState={activeForm.formState}
                isLocked={false}
                key={`${collectionSlug}-${activeIndex}-${forms.length}`}
                lastUpdateTime={0}
                mostRecentVersionIsAutosaved={false}
                unpublishedVersionCount={0}
                Upload={documentSlots.Upload}
                versionCount={0}
              >
                <EditForm
                  resetUploadEdits={resetUploadEdits}
                  submitted={hasSubmitted}
                  updateUploadEdits={updateUploadEdits}
                  uploadEdits={activeForm?.uploadEdits}
                />
              </DocumentInfoProvider>
            ) : null}
          </div>
        </div>

        <ActionsBar />

        {/* Nested Modals */}
        <AddFilesView
          acceptMimeTypes={collectionConfig?.upload?.mimeTypes?.join(', ')}
          modalSlug={addMoreFilesModalSlug}
          onDrop={handleAddFiles}
        />
        <DiscardWithoutSaving />
      </DialogModal>
    </>
  )
}

elements/BulkUpload/DiscardWithoutSaving:
'use client'

import { useModal } from '@faceless-ui/modal'
import React from 'react'

import { useTranslation } from '../../../providers/Translation/index.js'
import { ConfirmationModal } from '../../ConfirmationModal/index.js'
import { useBulkUpload } from '../index.js'
export const discardBulkUploadModalSlug = 'bulk-upload--discard-without-saving'

export function DiscardWithoutSaving() {
  const { t } = useTranslation()
  const { closeModal } = useModal()
  const { modalSlug } = useBulkUpload()

  const onCancel = React.useCallback(() => {
    closeModal(discardBulkUploadModalSlug)
  }, [closeModal])

  const onConfirm = React.useCallback(() => {
    closeModal(modalSlug)
    closeModal(discardBulkUploadModalSlug)
  }, [closeModal, modalSlug])

  return (
    <ConfirmationModal
      body={t('general:changesNotSaved')}
      cancelLabel={t('general:stayOnThisPage')}
      confirmLabel={t('general:leaveAnyway')}
      heading={t('general:leaveWithoutSaving')}
      modalSlug={discardBulkUploadModalSlug}
      onCancel={onCancel}
      onConfirm={onConfirm}
    />
  )
}

