    text-decoration: none;
    color: inherit;
    background-color: transparent;

    &.btn--disabled {
      cursor: not-allowed;
    }
  }

  .btn--disabled,
  .btn--disabled .btn {
    cursor: not-allowed;
  }

  /* Style variants */

  .btn--style-primary {
    color: var(--color-text-onbrand);
    background-color: var(--color-bg-brand);

    &:hover:not(.btn--disabled) {
      background-color: var(--color-bg-brand-hover);
    }

    &:active:not(.btn--disabled) {
      background-color: var(--color-bg-brand-pressed);
    }

    &.btn--disabled:not(.btn--loading) {
      color: var(--color-text-ondisabled);
      background-color: var(--color-bg-disabled);
    }
  }

  .btn--style-primary-ghost {
    color: var(--color-text-brand);
    background-color: transparent;

    &:hover:not(.btn--disabled) {
      background-color: var(--color-bg-brand-tertiary);
    }

    &:active:not(.btn--disabled) {
      background-color: var(--color-bg-brand-tertiary-hover);
    }

    &.btn--disabled {
      color: var(--color-text-disabled);
    }
  }

  .btn.btn--style-secondary {
    color: var(--color-text);
    background-color: var(--color-bg);
    border: var(--stroke-width-small) solid var(--special-border-translucent);

    &:hover:not(.btn--disabled) {
      background-color: var(--color-bg-secondary-hover);
    }

    &:active:not(.btn--disabled) {
      background-color: var(--color-bg-secondary-pressed);
    }

    &.btn--disabled {
      color: var(--color-text-disabled);
