'use client'
import type { HTMLAttributes } from 'react'

import React from 'react'

import { XIcon } from '../../icons/X/index.js'
import { useTranslation } from '../../providers/Translation/index.js'
import './index.css'

const baseClass = 'chip'

export type ChipVariant = 'danger' | 'default' | 'success' | 'warning'

export type ChipProps = {
  'aria-label'?: string
  children: React.ReactNode
  className?: string
  disabled?: boolean
  elementProps?: {
    ref?: React.RefCallback<HTMLElement>
  } & HTMLAttributes<HTMLElement>
  icon?: React.ReactNode
  id?: string
  onClick?: () => void
  onRemove?: () => void
  selected?: boolean
  size?: 'large' | 'medium'
  variant?: ChipVariant
}

export const Chip: React.FC<ChipProps> = ({
  id,
  'aria-label': ariaLabel,
  children,
  className,
  disabled,
  elementProps,
  icon,
  onClick,
  onRemove,
  selected,
  size = 'medium',
  variant = 'default',
}) => {
  const { t } = useTranslation()

  const classes = [
    baseClass,
    `${baseClass}--size-${size}`,
    `${baseClass}--variant-${variant}`,
    selected && `${baseClass}--selected`,
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return (
    <div {...elementProps} className={classes} id={id} ref={elementProps?.ref}>
      {onClick ? (
        <button
          aria-label={ariaLabel}
          className={`${baseClass}__action`}
          disabled={disabled}
          onClick={onClick}
          type="button"
        />
      ) : null}
      {icon ? <span className={`${baseClass}__icon`}>{icon}</span> : null}
      <span className={`${baseClass}__label`}>{children}</span>
      {onRemove ? (
        <button
          aria-label={t('general:remove')}
          className={`${baseClass}__remove`}
          disabled={disabled}
          onClick={onRemove}
          type="button"
        >
          <XIcon size={24} />
        </button>
      ) : null}
    </div>
  )
}

elements/ClipboardAction/ClipboardAction:
'use client'

import { Fragment } from 'react'

import { ClipboardIcon } from '../../icons/Clipboard/index.js'
import { CopyIcon } from '../../icons/Copy/index.js'
import { useTranslation } from '../../providers/Translation/index.js'

export const ClipboardActionLabel = ({
  isPaste,
  isRow,
}: {
  isPaste?: boolean
  isRow?: boolean
}) => {
  const { t } = useTranslation()

  let label = t('general:copyField')
  if (!isRow && isPaste) {
    label = t('general:pasteField')
  } else if (isRow && !isPaste) {
    label = t('general:copyRow')
  } else if (isRow && isPaste) {
    label = t('general:pasteRow')
  }

  return (
    <Fragment>
      {isPaste ? <ClipboardIcon /> : <CopyIcon />} {label}
    </Fragment>
  )
}

elements/ClipboardAction/clipboardUtilit:
import type {
  ClipboardCopyActionArgs,
  ClipboardPasteActionArgs,
  ClipboardPasteActionValidateArgs,
  ClipboardPasteData,
  ClipboardPasteEligibilityArgs,
} from './types.js'

import { isClipboardDataValid } from './isClipboardDataValid.js'

const localStorageClipboardKey = '_payloadClipboard'

/**
 * Reads and parses the clipboard data from localStorage.
 *
 * @note This function doesn't use the Clipboard API, but localStorage. See rationale in #11513
 */
function readClipboardData(): ClipboardPasteData | null {
  try {
    const jsonFromClipboard = localStorage.getItem(localStorageClipboardKey)

    if (!jsonFromClipboard) {
      return null
    }

    return JSON.parse(jsonFromClipboard)
  } catch (_err) {
    return null
  }
}

/**
 * Whether the clipboard contents can be pasted into the target field.
 *
 * Returns `false` when the clipboard is empty or its schema is incompatible
 * with the target. Used to disable paste actions when they would fail.
 */
export function canPasteClipboardData(args: ClipboardPasteEligibilityArgs): boolean {
  const dataToPaste = readClipboardData()

  if (!dataToPaste) {
    return false
  }

  const { path, ...schemaArgs } = args

  const dataToValidate = {
    ...dataToPaste,
    ...schemaArgs,
    fieldPath: path,
  } as ClipboardPasteActionValidateArgs

  return isClipboardDataValid(dataToValidate)
}

/**
 * @note This function doesn't use the Clipboard API, but localStorage. See rationale in #11513
 */
export function clipboardCopy(args: ClipboardCopyActionArgs): string | true {
  const { getDataToCopy, t, ...rest } = args

  const dataToWrite = {
    data: getDataToCopy(),
    ...rest,
  }

  try {
    localStorage.setItem(localStorageClipboardKey, JSON.stringify(dataToWrite))
    return true
  } catch (_err) {
    return t('error:unableToCopy')
  }
}

/**
 * @note This function doesn't use the Clipboard API, but localStorage. See rationale in #11513
 */
export function clipboardPaste({
  onPaste,
  path: fieldPath,
  t,
  ...args
}: ClipboardPasteActionArgs): string | true {
  const dataToPaste = readClipboardData()

  if (!dataToPaste) {
    return t('error:invalidClipboardData')
  }

  const dataToValidate = {
    ...dataToPaste,
    ...args,
    fieldPath,
  } as ClipboardPasteActionValidateArgs

  if (!isClipboardDataValid(dataToValidate)) {
    return t('error:invalidClipboardData')
  }

  onPaste(dataToPaste)

  return true
}

