'use client'

import type { FormStateWithoutComponents } from 'payload'

import { type FC, useCallback } from 'react'
import { toast } from 'sonner'

import type { ClipboardCopyData, OnPasteFn } from './types.js'

import { ClipboardIcon } from '../../icons/Clipboard/index.js'
import { CopyIcon } from '../../icons/Copy/index.js'
import { MoreIcon } from '../../icons/More/index.js'
import { useTranslation } from '../../providers/Translation/index.js'
import { Popup, PopupList } from '../Popup/index.js'
import { clipboardCopy, clipboardPaste } from './clipboardUtilities.js'
import { useCanPasteClipboard } from './useCanPasteClipboard.js'
import './index.css'

const baseClass = 'clipboard-action'

type Props = {
  allowCopy?: boolean
  allowPaste?: boolean
  className?: string
  copyClassName?: string
  disabled?: boolean
  getDataToCopy: () => FormStateWithoutComponents
  isRow?: boolean
  onPaste: OnPasteFn
  pasteClassName?: string
} & ClipboardCopyData

/**
 * Menu actions for copying and pasting fields. Currently, this is only used in Arrays and Blocks.
 * @note This component doesn't use the Clipboard API, but localStorage. See rationale in #11513
 */
export const ClipboardAction: FC<Props> = ({
  allowCopy,
  allowPaste,
  className,
  copyClassName,
  disabled,
  isRow,
  onPaste,
  pasteClassName,
  path,
  ...rest
}) => {
  const { t } = useTranslation()

  const { canPaste, refresh } = useCanPasteClipboard(
    rest.type === 'array'
      ? { path, schemaFields: rest.fields }
      : { path, schemaBlocks: rest.blocks },
  )

  const classes = [`${baseClass}__popup`, className].filter(Boolean).join(' ')

  const handleCopy = useCallback(() => {
    const clipboardResult = clipboardCopy({
      path,
      t,
      ...rest,
    })

    if (typeof clipboardResult === 'string') {
      toast.error(clipboardResult)
    } else {
      toast.success(t('general:copied'))
    }
  }, [t, rest, path])

  const handlePaste = useCallback(() => {
    const clipboardResult = clipboardPaste(
      rest.type === 'array'
        ? {
            onPaste,
            path,
            schemaFields: rest.fields,
            t,
          }
        : {
            onPaste,
            path,
            schemaBlocks: rest.blocks,
            t,
          },
    )

    if (typeof clipboardResult === 'string') {
      toast.error(clipboardResult)
    }
  }, [onPaste, rest, path, t])

  if (!allowPaste && !allowCopy) {
    return null
  }

  return (
    <Popup
      button={<MoreIcon />}
      buttonAriaLabel={t('general:moreOptions')}
      buttonClassName={`${baseClass}__button`}
      caret={false}
      className={classes}
      disabled={disabled}
      horizontalAlign="right"
      onToggleOpen={(active) => {
        if (active) {
          refresh()
        }
      }}
      popupType="menu"
      render={({ close }) => (
        <PopupList.MenuItem>
          <PopupList.Button
            className={copyClassName}
            disabled={!allowCopy}
            icon={<CopyIcon size={24} />}
            onClick={() => {
              void handleCopy()
              close()
            }}
          >
            {isRow ? t('general:copyRow') : t('general:copyField')}
          </PopupList.Button>
          <PopupList.Button
            className={pasteClassName}
            disabled={!allowPaste || !canPaste}
            icon={<ClipboardIcon />}
            onClick={() => {
              void handlePaste()
              close()
            }}
          >
            {isRow ? t('general:pasteRow') : t('general:pasteField')}
          </PopupList.Button>
        </PopupList.MenuItem>
      )}
      verticalAlign="bottom"
    />
  )
}

elements/ClipboardAction/isClipboardData:
import type { ClientBlock, ClientField } from 'payload'

import { fieldAffectsData, fieldHasSubFields } from 'payload/shared'

import type { ClipboardPasteActionValidateArgs } from './types.js'

/**
 * Validates whether clipboard data is compatible with the target schema.
 * For this to be true, the copied field and the target to be pasted must
 * be structurally equivalent (same schema)
 *
 * @returns True if the clipboard data is valid and can be pasted, false otherwise
 */
export function isClipboardDataValid({ data, path, ...args }: ClipboardPasteActionValidateArgs) {
  if (typeof data === 'undefined' || !path || !args.type) {
    return false
  }

  if (args.type === 'blocks') {
    return isClipboardBlocksValid({
      blocksFromClipboard: args.blocks,
      blocksFromConfig: args.schemaBlocks,
    })
  } else {
    return isClipboardFieldsValid({
      fieldsFromClipboard: args.fields,
      fieldsFromConfig: args.schemaFields,
    })
  }
}

function isClipboardFieldsValid({
  fieldsFromClipboard,
  fieldsFromConfig,
}: {
  fieldsFromClipboard: ClientField[]
  fieldsFromConfig?: ClientField[]
}): boolean {
  if (!fieldsFromConfig || fieldsFromClipboard.length !== fieldsFromConfig?.length) {
    return false
  }

  return fieldsFromClipboard.every((clipboardField, i) => {
    const configField = fieldsFromConfig[i]

    if (clipboardField.type !== configField.type) {
      return false
    }

    const affectsData = fieldAffectsData(clipboardField) && fieldAffectsData(configField)
    if (affectsData && clipboardField.name !== configField.name) {
      return false
    }

    const hasNestedFieldsConfig = fieldHasSubFields(configField)
    const hasNestedFieldsClipboard = fieldHasSubFields(clipboardField)
    if (hasNestedFieldsClipboard !== hasNestedFieldsConfig) {
      return false
    }

    if (hasNestedFieldsClipboard && hasNestedFieldsConfig) {
      return isClipboardFieldsValid({
        fieldsFromClipboard: clipboardField.fields,
        fieldsFromConfig: configField.fields,
      })
    }

    return true
  })
}

function isClipboardBlocksValid({
  blocksFromClipboard,
  blocksFromConfig,
}: {
  blocksFromClipboard: ClientBlock[]
  blocksFromConfig?: ClientBlock[]
}) {
  const configBlockMap = new Map(blocksFromConfig?.map((block) => [block.slug, block]))

  if (!configBlockMap.size) {
    return false
  }

  const checkedSlugs = new Set<string>()

  for (const currBlock of blocksFromClipboard) {
    const currSlug = currBlock.slug

    if (!checkedSlugs.has(currSlug)) {
      const configBlock = configBlockMap.get(currSlug)
      if (!configBlock) {
        return false
      }

      if (
        !isClipboardFieldsValid({
          fieldsFromClipboard: currBlock.fields,
          fieldsFromConfig: configBlock.fields,
        })
      ) {
        return false
      }

      checkedSlugs.add(currSlug)
    }
  }
  return true
}

elements/ClipboardAction/mergeFormStateF:
import type { FieldState, FormState, Row } from 'payload'

import ObjectIdImport from 'bson-objectid'

import type { ClipboardPasteData } from './types.js'

import { flattenRows, separateRows } from '../../forms/Form/rows.js'

const ObjectId = 'default' in ObjectIdImport ? ObjectIdImport.default : ObjectIdImport

// Strict path-prefix check: matches `prefix` exactly, or any descendant path (`prefix.`).
// Required because numeric row indices share digit prefixes (`.1` vs `.10`/`.11`), and
// field names can also share textual prefixes (`children` vs `childrenOther`). A loose
// `startsWith(prefix)` leaks unrelated keys into clipboard / cleanup operations.
function isStrictPathPrefix(key: string, prefix: string): boolean {
  return key === prefix || key.startsWith(`${prefix}.`)
}

export function reduceFormStateByPath({
  formState,
  path,
  rowIndex,
}: {
  formState: FormState
  path: string
  rowIndex?: number
}) {
  const filteredState: Record<string, FieldState> = {}
  const prefix = typeof rowIndex !== 'number' ? path : `${path}.${rowIndex}`

  for (const key in formState) {
    if (!isStrictPathPrefix(key, prefix)) {
      continue
    }

    const { customComponents: _, validate: __, ...field } = formState[key]

    if (Array.isArray(field.rows)) {
      field.rows = field.rows.map((row) => {
        if (!row || typeof row !== 'object') {
          return row
        }
        const { customComponents: _, ...serializableRow } = row
        return serializableRow
      })
    }

    filteredState[key] = field
  }

  return filteredState
}

export function mergeFormStateFromClipboard({
  dataFromClipboard: clipboardData,
  formState,
  path,
  rowIndex,
}: {
  dataFromClipboard: ClipboardPasteData
  formState: FormState
  path: string
  rowIndex?: number
}) {
  const {
    type: typeFromClipboard,
    data: dataFromClipboard,
    path: pathFromClipboard,
    rowIndex: rowIndexFromClipboard,
  } = clipboardData

  const copyFromField = typeof rowIndexFromClipboard !== 'number'
  const pasteIntoField = typeof rowIndex !== 'number'
  const fromRowToField = !copyFromField && pasteIntoField
  const isArray = typeFromClipboard === 'array'

  let pathToReplace: string
  if (copyFromField && pasteIntoField) {
    pathToReplace = pathFromClipboard
  } else if (copyFromField) {
    pathToReplace = `${pathFromClipboard}.${rowIndex}`
  } else {
    pathToReplace = `${pathFromClipboard}.${rowIndexFromClipboard}`
  }

  let targetSegment: string
  if (!pasteIntoField) {
    targetSegment = `${path}.${rowIndex}`
  } else if (fromRowToField) {
    targetSegment = `${path}.0`
  } else {
    targetSegment = path
  }

  if (fromRowToField) {
    const lastRenderedPath = `${path}.0`
    const rowIDFromClipboard = dataFromClipboard[`${pathToReplace}.id`]?.value as string
    const hasRows = formState[path].rows?.length

    formState[path].rows = [
      {
        ...(hasRows && isArray ? formState[path].rows[0] : {}),
        id: rowIDFromClipboard,
        isLoading: false,
        lastRenderedPath,
      },
    ]
    formState[path].value = 1
    formState[path].initialValue = 1
    formState[path].disableFormData = true

    for (const fieldPath in formState) {
      if (
        fieldPath !== path &&
        !isStrictPathPrefix(fieldPath, lastRenderedPath) &&
        isStrictPathPrefix(fieldPath, path)
      ) {
        delete formState[fieldPath]
      }
    }
  }

  // Map to track old IDs to new IDs for regenerating nested IDs
  const idReplacements: Map<string, string> = new Map()

  for (const clipboardPath in dataFromClipboard) {
    // When pasting into a specific row, skip only the direct row ID to avoid overwriting
    // the target row's identity. Nested IDs (array item IDs within the block) should
    // still be processed so they get regenerated below, preventing server-side duplication.
    if (
      (!pasteIntoField && clipboardPath === `${pathToReplace}.id`) ||
      !isStrictPathPrefix(clipboardPath, pathToReplace)
    ) {
      continue
    }

    const newPath = clipboardPath.replace(pathToReplace, targetSegment)

    const customComponents = isArray ? formState[newPath]?.customComponents : undefined
    const validate = isArray ? formState[newPath]?.validate : undefined

    // If this is an ID field, generate a new ID to prevent duplicates
    if (clipboardPath.endsWith('.id') && dataFromClipboard[clipboardPath]?.value) {
      const oldID = dataFromClipboard[clipboardPath].value as string
      if (typeof oldID === 'string' && ObjectId.isValid(oldID)) {
        const newID = new ObjectId().toHexString()
        idReplacements.set(clipboardPath, newID)

        formState[newPath] = {
          customComponents,
          validate,
          ...dataFromClipboard[clipboardPath],
          initialValue: newID,
          value: newID,
        }
        continue
      }
    }

    formState[newPath] = {
      customComponents,
      validate,
      ...dataFromClipboard[clipboardPath],
    }
  }

  // Update parent field rows with new IDs
  for (const [clipboardPath, newID] of idReplacements) {
    const relativePath = clipboardPath.replace(`${pathToReplace}.`, '')
    const segments = relativePath.split('.')

    if (segments.length >= 2) {
      const rowIndex = parseInt(segments[segments.length - 2], 10)
      const parentFieldPath = segments.slice(0, segments.length - 2).join('.')
      const fullParentPath = parentFieldPath ? `${targetSegment}.${parentFieldPath}` : targetSegment

      if (formState[fullParentPath] && Array.isArray(formState[fullParentPath].rows)) {
        const parentRows = formState[fullParentPath].rows
        if (!isNaN(rowIndex) && parentRows[rowIndex]) {
          parentRows[rowIndex].id = newID
        }
      }
    } else if (segments.length === 1 && segments[0] === 'id') {
      // Top-level block ID - extract field path and row index from targetSegment
      const targetParts = targetSegment.split('.')
      const lastPart = targetParts[targetParts.length - 1]
      const rowIndexFromTarget = !isNaN(parseInt(lastPart, 10)) ? parseInt(lastPart, 10) : 0
      const fieldPath = !isNaN(parseInt(lastPart, 10))
        ? targetParts.slice(0, -1).join('.')
        : targetSegment

      if (formState[fieldPath] && Array.isArray(formState[fieldPath].rows)) {
        const rows = formState[fieldPath].rows
        if (rows[rowIndexFromTarget]) {
          rows[rowIndexFromTarget].id = newID
        }
      }
    }
  }

  return formState
}

/**
 * Inserts a new row at `rowIndex`, populated with clipboard data, without disturbing
 * any existing rows. Existing rows at and after `rowIndex` are shifted down by one.
 */
export function insertRowFromClipboard({
  dataFromClipboard: clipboardData,
  formState,
  path,
  rowIndex,
}: {
  dataFromClipboard: ClipboardPasteData
  formState: FormState
  path: string
  rowIndex: number
}): FormState {
  const { path: pathFromClipboard, rowIndex: rowIndexFromClipboard } = clipboardData

  const sourceRowPath =
    typeof rowIndexFromClipboard === 'number'
      ? `${pathFromClipboard}.${rowIndexFromClipboard}`
      : pathFromClipboard

  const blockType = clipboardData.data[`${sourceRowPath}.blockType`]?.value as string | undefined

  const newRowID = new ObjectId().toHexString()

  const { remainingFields, rows } = separateRows(path, formState)

  rows.splice(rowIndex, 0, {
    id: { initialValue: newRowID, valid: true, value: newRowID },
  })

  const newRows = [...(formState[path].rows || [])]
  const newRow: Row = { id: newRowID, isLoading: false }
  if (blockType) {
    newRow.blockType = blockType
  }
  newRows.splice(rowIndex, 0, newRow)

  const formStateWithNewRow: FormState = {
    ...remainingFields,
    ...flattenRows(path, rows),
    [path]: { ...formState[path], disableFormData: true, rows: newRows, value: rows.length },
  }

  return mergeFormStateFromClipboard({
    dataFromClipboard: clipboardData,
    formState: formStateWithNewRow,
    path,
    rowIndex,
  })
}

