import type { FuzzyMatchResult } from '../../utilities/fuzzyMatch.js'
import type { CommandPaletteAction, CommandPaletteGroup } from './types.js'

import { fuzzyMatch } from '../../utilities/fuzzyMatch.js'

/**
 * Fuzzy-filters each group's actions against the query, ranks survivors by score
 * (descending), and removes groups left with no matches. An empty query returns
 * the groups unchanged.
 */
export function filterActions(groups: CommandPaletteGroup[], query: string): CommandPaletteGroup[] {
  if (!query) {
    return groups
  }

  return groups.reduce<CommandPaletteGroup[]>((filtered, group) => {
    const actions = group.actions
      .map((action) => ({ action, match: fuzzyMatch(query, action.label) }))
      .filter(
        (scored): scored is { action: CommandPaletteAction; match: FuzzyMatchResult } =>
          scored.match !== null,
      )
      .sort((a, b) => b.match.score - a.match.score)
      .map((scored) => ({ ...scored.action, matchIndices: scored.match.indices }))

    if (actions.length > 0) {
      filtered.push({ ...group, actions })
    }

    return filtered
  }, [])
}

elements/CommandPalette/highlightLabel.t:
export type LabelSegment = { isMatch: boolean; text: string }

/**
 * Splits `label` into consecutive matched / unmatched runs based on `indices`
 * (ascending positions into `label`). Used to render fuzzy-match highlighting.
 * Empty/absent indices yield a single unmatched segment containing the whole label.
 */
export function splitLabelByMatches(label: string, indices?: number[]): LabelSegment[] {
  if (!label) {
    return []
  }

  if (!indices || indices.length === 0) {
    return [{ isMatch: false, text: label }]
  }

  const matchSet = new Set(indices)
  const segments: LabelSegment[] = []
  let currentText = ''
  let currentIsMatch = matchSet.has(0)

  for (let i = 0; i < label.length; i++) {
    const isMatch = matchSet.has(i)

    if (isMatch !== currentIsMatch) {
      if (currentText) {
        segments.push({ isMatch: currentIsMatch, text: currentText })
      }
      currentText = label[i]
      currentIsMatch = isMatch
    } else {
      currentText += label[i]
    }
  }

  if (currentText) {
    segments.push({ isMatch: currentIsMatch, text: currentText })
  }

  return segments
}

