@layer payload-default {
  /* ——————————————————————————————————————————————
     react-datepicker library base styles
     ————————————————————————————————————————————— */

  .react-datepicker-wrapper {
    display: block;
    padding: 0;
    border: 0;
  }

  /* Visually hidden labels, e.g. full weekday names read instead of "Su", "Mo", ...
     (copied from react-datepicker's stylesheet) */
  .react-datepicker__sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  .react-datepicker {
    --time-column-width: 120px;
    font-size: var(--text-body-medium-font-size);
    font-weight: var(--text-body-medium-font-weight);
    line-height: var(--text-body-medium-line-height);
    letter-spacing: var(--text-letter-spacing);
    background-color: var(--color-bg);
    color: var(--color-text);
    border: none;
    border-radius: var(--radius-large);
    display: inline-flex;
    /* Don't stretch the calendar and time columns to the same height. react-datepicker sizes the
       time list from the calendar's height and re-measures it on resize, so stretching would make
       both grow forever. The library's own float layout doesn't stretch either. */
    align-items: flex-start;
    position: relative;
    /* stylelint-disable-next-line plugin/no-subpixel-values -- TODO: pre-existing; revisit this sub-pixel value */
    box-shadow:
      0 0 0.25px rgba(0, 0, 0, 0.08),
      0 2px 2.5px rgba(0, 0, 0, 0.15),
      0 10px 12px rgba(0, 0, 0, 0.18);
  }

  .react-datepicker--time-only .react-datepicker__time,
  .react-datepicker--time-only .react-datepicker__time-box {
    border-bottom-left-radius: var(--radius-large);
    border-bottom-right-radius: var(--radius-large);
  }

  .react-datepicker--time-only .react-datepicker__time-container {
    border-left: none;
  }

  .react-datepicker-popper {
    z-index: var(--z-portal-element);
    line-height: 0;
  }

  .react-datepicker-popper .react-datepicker__triangle {
    display: none;
  }

  /* ——————————————————————————————————————————————
     Header
     ————————————————————————————————————————————— */

  .react-datepicker__header {
    display: flex;
    align-items: center;
    text-align: center;
    text-transform: none;
    background-color: transparent;
    border-bottom: none;
    border-radius: 0;
    padding: 0;
    position: relative;
    /* Fill the calendar's width, but don't let the dropdowns make the calendar wider */
    contain: inline-size;

    & h2 {
      display: none;
    }

    &:not(.react-datepicker__header--has-time-select) {
      border-top-right-radius: var(--radius-large);
    }
  }

  .react-datepicker__header--time {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: var(--spacer-2);
    border-top-left-radius: 0;
    border-top-right-radius: var(--radius-large);
    font-weight: var(--text-body-medium-bold-font-weight);
    min-height: calc(var(--spacer-4) + var(--spacer-2) * 2);
    width: 100%;
  }

  .react-datepicker__current-month {
    display: none;
  }

  .react-datepicker-time__header {
    margin-top: 0;
    color: var(--color-text);
    font-size: var(--text-body-medium-bold-font-size);
    font-weight: var(--text-body-medium-bold-font-weight);
    line-height: var(--text-body-medium-bold-line-height);
    text-overflow: ellipsis;
    white-space: nowrap;
    overflow: hidden;
  }

  .react-datepicker__header__dropdown {
    display: flex;
    flex: 1 1 auto;
    min-width: min-content;
    gap: var(--spacer-2);
    align-items: center;
    padding: var(--spacer-2);
    margin: 0 var(--spacer-5);
  }

  .react-datepicker-year-header {
    padding: var(--spacer-2-5) 0;
    font-weight: var(--text-body-medium-bold-font-weight);
    color: var(--color-text);
    width: 100%;
    display: flex;
    justify-content: center;
  }

  .react-datepicker__month-select,
  .react-datepicker__year-select {
    width: 100%;
    margin: 0;
    height: var(--spacer-4);
    border: var(--stroke-width-small) solid var(--color-border);
    background: var(--color-bg);
    border-radius: var(--radius-medium);
    outline: none;
    cursor: pointer;
    padding: 0 var(--spacer-2);
    color: var(--color-text);
    font-size: var(--text-body-medium-font-size);
    font-weight: var(--text-body-medium-font-weight);
    -webkit-appearance: none;
    appearance: none;
    background-image: none;
    padding-right: var(--spacer-4);

    &:focus-visible {
      outline: var(--accessibility-outline);
      outline-offset: calc(var(--accessibility-outline-offset) * 2);
    }

    option {
      background-color: var(--color-bg);
      color: var(--color-text);
    }
  }

  /* ——————————————————————————————————————————————
     Navigation arrows
     ————————————————————————————————————————————— */

  .react-datepicker__navigation {
    position: absolute;
    align-items: center;
    background: none;
    display: flex;
    justify-content: center;
    text-align: center;
    cursor: pointer;
    top: 0;
    margin: var(--spacer-2);
    border: none;
    z-index: 1;
    height: var(--spacer-4);
    width: var(--spacer-4);
    overflow: hidden;
    color: var(--color-icon);
    border-radius: var(--radius-medium);
    flex-shrink: 0;

    .icon--chevron .fill {
      fill: var(--color-icon);
    }

    &:hover {
      background-color: var(--color-bg-hover);
    }
  }

  .date-time-picker__appearance--monthOnly .react-datepicker__navigation {
    font-size: 18px;
    font-weight: 300;
  }

  .react-datepicker__navigation-icon {
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .react-datepicker__navigation--years {
    position: relative;
    top: 0;
    display: block;
    margin-left: auto;
    margin-right: auto;
  }

  .react-datepicker__navigation--years-previous {
    top: var(--spacer-1);
  }

  .react-datepicker__navigation--years-upcoming {
    top: calc(-1 * var(--spacer-1));
  }

  .react-datepicker__navigation--previous {
    left: 0;
  }

  .react-datepicker__navigation--next {
    right: 0;
  }

  .react-datepicker__navigation--next--with-time:not(
      .react-datepicker__navigation--next--with-today-button
    ) {
    right: var(--time-column-width);
  }

  /* ——————————————————————————————————————————————
     Dropdowns (month, year)
     ————————————————————————————————————————————— */

  .react-datepicker__year-dropdown-container--select,
  .react-datepicker__month-dropdown-container--select,
  .react-datepicker__month-year-dropdown-container--select {
    display: inline-block;
    flex: 1 1 auto;
