  .react-datepicker__month-read-view--down-arrow,
  .react-datepicker__month-year-read-view--down-arrow {
    border-color: var(--color-icon-secondary);
    border-style: solid;
    border-width: var(--stroke-width-medium) var(--stroke-width-medium) 0 0;
    content: '';
    display: block;
    height: 6px;
    position: absolute;
    top: 4px;
    width: 6px;
    transform: rotate(135deg);
    right: -1rem;
  }

  .react-datepicker__year-dropdown,
  .react-datepicker__month-dropdown,
  .react-datepicker__month-year-dropdown {
    background-color: var(--color-bg-elevated);
    position: absolute;
    width: 50%;
    left: 25%;
    top: 30px;
    z-index: 1;
    text-align: center;
    border-radius: var(--radius-medium);
    border: var(--stroke-width-small) solid var(--color-border);
    box-shadow:
      0 2px 5px rgba(0, 0, 0, 0.15),
      0 10px 24px rgba(0, 0, 0, 0.18);

    &:hover {
      cursor: pointer;
    }
  }

  .react-datepicker__year-dropdown--scrollable,
  .react-datepicker__month-dropdown--scrollable,
  .react-datepicker__month-year-dropdown--scrollable {
    height: 150px;
    overflow-y: scroll;
  }

  .react-datepicker__year-option,
  .react-datepicker__month-option,
  .react-datepicker__month-year-option {
    line-height: 1.25rem;
    width: 100%;
    display: block;
    margin-left: auto;
    margin-right: auto;
    color: var(--color-text);

    &:first-of-type {
      border-top-left-radius: var(--radius-medium);
      border-top-right-radius: var(--radius-medium);
    }

    &:last-of-type {
      user-select: none;
      border-bottom-left-radius: var(--radius-medium);
      border-bottom-right-radius: var(--radius-medium);
    }

    &:hover {
      background-color: var(--color-bg-hover);
    }
  }

  .react-datepicker__year-option--selected,
  .react-datepicker__month-option--selected,
  .react-datepicker__month-year-option--selected {
    position: absolute;
    left: 15px;
  }

  /* ——————————————————————————————————————————————
     Month container
     ————————————————————————————————————————————— */

  .react-datepicker__month-container {
    position: relative;
  }

  .react-datepicker__month {
    margin: 0;
    padding: var(--spacer-1);
    text-align: center;

    .react-datepicker__month-text,
    .react-datepicker__quarter-text {
      display: inline-block;
      width: 52px;
      margin: var(--spacer-1);
      height: var(--spacer-4);
      padding: var(--spacer-1, 0.3rem) var(--spacer-2-5, 0.75rem);
    }
  }

  .react-datepicker__monthPicker {
    border-top: var(--stroke-width-small) solid var(--color-border);
  }

  .react-datepicker__month-text {
    padding: var(--spacer-1);
    font-size: var(--text-body-medium-font-size);
    border-radius: var(--radius-medium);
  }

  /* ——————————————————————————————————————————————
     Year view
     ————————————————————————————————————————————— */

  .react-datepicker__year {
    margin: var(--spacer-1);
    text-align: center;
  }

  .react-datepicker__year-wrapper {
    display: flex;
    flex-wrap: wrap;
    max-width: 180px;
  }

  .react-datepicker__year .react-datepicker__year-text {
    display: inline-block;
    width: 4rem;
    margin: 2px;
  }

  /* ——————————————————————————————————————————————
     Day names & days
     ————————————————————————————————————————————— */

  .react-datepicker__day-names {
    white-space: nowrap;
    margin-bottom: 0;
    background-color: transparent;
    padding: var(--spacer-2);
    padding-bottom: 0;
    border-top: var(--stroke-width-small) solid var(--color-border);
    width: 100%;
  }

  .react-datepicker__week {
    white-space: nowrap;
  }

  .react-datepicker__day-name,
  .react-datepicker__day,
  .react-datepicker__time-name {
    color: var(--color-text);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    line-height: var(--text-body-medium-line-height);
    text-align: center;
    margin: 0;
    font-size: var(--text-body-medium-font-size);
    font-weight: var(--text-body-medium-font-weight);
    position: relative;
  }

  .react-datepicker__day-name {
    color: var(--color-text-secondary);
    width: 1.5rem;
    height: 2rem;
    margin: 0 var(--spacer-1);
    line-height: 2rem;
  }

  .react-datepicker__day {
    width: 1.5rem;
    height: 1.5rem;
    margin: var(--spacer-1);
    line-height: 1.5rem;

    &:focus {
      outline: 0;
    }
  }

  .react-datepicker__day,
  .react-datepicker__month-text,
  .react-datepicker__quarter-text,
  .react-datepicker__year-text {
    cursor: pointer;
    border-radius: var(--radius-medium);

    &:hover {
      background-color: var(--color-bg-hover);
    }

    &:active {
      background-color: var(--color-bg-pressed);
    }
  }

  .react-datepicker__day--today {
    font-weight: var(--text-body-medium-font-weight);
    position: relative;

    &::after {
      content: '';
      position: absolute;
      bottom: var(--spacer-1);
      left: 50%;
      transform: translate3D(-50%, 50%, 0);
      width: 3px;
      height: 3px;
      border-radius: var(--radius-full);
      background-color: var(--color-bg-brand);
    }

    &.react-datepicker__day--selected::after {
      background-color: var(--color-icon-onbrand-secondary);
    }
  }

  /* Outside month days (prev/next month) */
  .react-datepicker__day--outside-month {
    visibility: hidden;
  }

  /* Selected day */
  .react-datepicker__day--selected,
  .react-datepicker__day--in-selecting-range,
  .react-datepicker__day--in-range,
  .react-datepicker__month-text--selected,
  .react-datepicker__month-text--in-selecting-range,
  .react-datepicker__month-text--in-range,
  .react-datepicker__quarter-text--selected,
  .react-datepicker__quarter-text--in-selecting-range,
  .react-datepicker__quarter-text--in-range,
  .react-datepicker__year-text--selected,
  .react-datepicker__year-text--in-selecting-range,
  .react-datepicker__year-text--in-range {
    background-color: var(--color-bg-selected-strong);
    color: var(--color-text-onselected-strong);
    font-weight: var(--text-body-medium-font-weight);

    &:hover {
      background-color: var(--color-bg-selected-strong-hover);
    }
  }

  .react-datepicker__day--keyboard-selected,
  .react-datepicker__month-text--keyboard-selected,
  .react-datepicker__quarter-text--keyboard-selected,
  .react-datepicker__year-text--keyboard-selected {
    background-color: var(--color-bg-selected);
    color: var(--color-text);

    &:hover {
      background-color: var(--color-bg-selected-hover);
    }
  }

  /* When focus is on the already-selected day, use white outline for contrast */
  .react-datepicker__day--selected[tabindex='0']:focus,
  .react-datepicker__month-text--selected[tabindex='0']:focus,
  .react-datepicker__quarter-text--selected[tabindex='0']:focus,
  .react-datepicker__year-text--selected[tabindex='0']:focus {
    outline: var(--accessibility-outline);
    outline-offset: var(--accessibility-outline-offset);
  }

  /* In-range selecting (partial selection) */
  .react-datepicker__day--in-selecting-range:not(
      .react-datepicker__day--in-range,
      .react-datepicker__month-text--in-range,
      .react-datepicker__quarter-text--in-range,
      .react-datepicker__year-text--in-range
    ),
  .react-datepicker__month-text--in-selecting-range:not(
      .react-datepicker__day--in-range,
      .react-datepicker__month-text--in-range,
      .react-datepicker__quarter-text--in-range,
      .react-datepicker__year-text--in-range
    ),
  .react-datepicker__quarter-text--in-selecting-range:not(
      .react-datepicker__day--in-range,
      .react-datepicker__month-text--in-range,
      .react-datepicker__quarter-text--in-range,
      .react-datepicker__year-text--in-range
    ),
  .react-datepicker__year-text--in-selecting-range:not(
      .react-datepicker__day--in-range,
      .react-datepicker__month-text--in-range,
      .react-datepicker__quarter-text--in-range,
      .react-datepicker__year-text--in-range
    ) {
    background-color: var(--color-bg-selected);
  }

  /* Disabled days */
  .react-datepicker__day--disabled,
  .react-datepicker__month-text--disabled,
  .react-datepicker__quarter-text--disabled,
  .react-datepicker__year-text--disabled {
    cursor: default;
    color: var(--color-text-disabled);

    &:hover {
      background-color: transparent;
    }
  }

  /* ——————————————————————————————————————————————
     Week number
     ————————————————————————————————————————————— */

  .react-datepicker__week-number {
    color: var(--color-text-tertiary);
    display: inline-block;
    width: 2rem;
    line-height: 2rem;
    text-align: center;
    margin: 0;
  }

  /* ——————————————————————————————————————————————
     Input container
     ————————————————————————————————————————————— */

  .react-datepicker__input-container {
    position: relative;
    display: inline-block;
    width: 100%;
  }

  /* ——————————————————————————————————————————————
     Time picker
     ————————————————————————————————————————————— */

  .react-datepicker__time-container {
    float: right;
    border-left: var(--stroke-width-small) solid var(--color-border);
    width: var(--time-column-width);

    .react-datepicker__time {
      position: relative;
      background: transparent;
      border-top: var(--stroke-width-small) solid var(--color-border);
      border-bottom-right-radius: var(--radius-large);

      .react-datepicker__time-box {
        width: var(--time-column-width);
        overflow-x: hidden;
        margin: 0 auto;
        text-align: center;
        border-bottom-right-radius: var(--radius-large);

        ul.react-datepicker__time-list {
          list-style: none;
          margin: 0;
          height: calc(195px + 0.85rem);
          max-height: 100%;
          overflow-y: scroll;
          scrollbar-width: none;
          padding: var(--spacer-1) 0;
          padding-right: 0;
          padding-left: 0;
          width: 100%;
          box-sizing: content-box;

          &::-webkit-scrollbar {
            display: none;
          }

          li.react-datepicker__time-list-item {
            height: auto;
            padding: var(--spacer-1) var(--spacer-2);
            white-space: nowrap;
            font-size: var(--text-body-medium-font-size);
            font-weight: var(--text-body-medium-font-weight);
            line-height: var(--text-body-medium-line-height);
            color: var(--color-text);
            margin: 0 var(--spacer-2);
            border-radius: var(--radius-medium);

            &:hover {
              cursor: pointer;
              background-color: var(--color-bg-hover);
            }

            &:active {
              background-color: var(--color-bg-pressed);
            }

            &:focus {
              background-color: var(--color-bg-selected);
              outline: none;
            }
          }

          li.react-datepicker__time-list-item--selected {
            background-color: var(--color-bg-brand);
            color: var(--color-text-onbrand);

            &:hover {
              background-color: var(--color-bg-brand-hover);
            }

            &:focus {
              background-color: var(--color-bg-brand);
            }
          }

          li.react-datepicker__time-list-item--disabled {
            color: var(--color-text-disabled);

            &:hover {
              cursor: default;
              background-color: transparent;
            }
          }
        }
      }
    }
  }

  .react-datepicker__input-time-container {
    clear: both;
    width: 100%;
    float: left;
    margin: var(--spacer-1) 0 var(--spacer-2) var(--spacer-3);
    text-align: left;
  }

  /* ——————————————————————————————————————————————
     Close icon
     ————————————————————————————————————————————— */

  .react-datepicker__close-icon {
    display: none;
  }

  /* ——————————————————————————————————————————————
     Today button
     ————————————————————————————————————————————— */

  .react-datepicker__today-button {
    background: var(--color-bg-secondary);
    border-top: var(--stroke-width-small) solid var(--color-border);
    cursor: pointer;
    text-align: center;
    font-weight: var(--text-body-medium-bold-font-weight);
    padding: var(--spacer-1) 0;
    clear: left;
    border-bottom-left-radius: var(--radius-large);
    border-bottom-right-radius: var(--radius-large);
  }

  /* ——————————————————————————————————————————————
     Portal
     ————————————————————————————————————————————— */

  .react-datepicker__portal {
    position: fixed;
    width: 100vw;
    height: 100vh;
    background-color: rgba(0, 0, 0, 0.8);
    left: 0;
    top: 0;
    justify-content: center;
    align-items: center;
    display: flex;
    z-index: 2147483647;
  }

  .react-datepicker__aria-live {
    position: absolute;
    clip-path: circle(0);
    border: 0;
    height: 1px;
    margin: -1px;
    overflow: hidden;
    padding: 0;
    width: 1px;
    white-space: nowrap;
  }

  .react-datepicker__children-container {
    width: 13.8rem;
    margin: var(--spacer-1);
    padding-right: 0.2rem;
    padding-left: 0.2rem;
    height: auto;
  }

  /* ——————————————————————————————————————————————
     DatePicker component styles
     ————————————————————————————————————————————— */

  [dir='rtl'] {
    .date-time-picker {
      .react-datepicker__input-container input {
        padding-right: var(--spacer-5);
      }
    }
  }

  .date-time-picker__icon-wrap {
    position: relative;
    z-index: 1;
  }

  .date-time-picker .icon--calendar,
  .date-time-picker__clear-button {
    position: absolute;
  }

  .date-time-picker .icon--calendar,
  .date-time-picker .icon--x {
    color: var(--color-icon-secondary);
    height: auto;
  }

  .date-time-picker__clear-button {
    top: var(--spacer-2);
    right: var(--spacer-5);
    appearance: none;
    background-color: transparent;
    border: none;
    outline: none;
    padding: 0;
    display: flex;
    cursor: pointer;
  }

  .date-time-picker .icon--calendar {
    top: var(--spacer-3);
    right: var(--spacer-1);
    pointer-events: none;
    transform: translateY(-50%);
  }

  .date-time-picker .icon--x {
    width: 1rem;
  }

  /* ——— Input field ——— */
  .date-time-picker .react-datepicker__input-container input {
    font-size: var(--text-body-medium-font-size);
    font-weight: var(--text-body-medium-font-weight);
    line-height: var(--text-body-medium-line-height);
    width: 100%;
    min-height: var(--field-min-height-large);
    border: var(--stroke-width-small) solid var(--field-color-border);
    border-radius: var(--field-border-radius);
    background: var(--field-color-bg);
    color: var(--color-text);
    padding-block: calc(var(--spacer-1));
    padding-inline: var(--field-padding-inline) var(--spacer-5); /* space for calendar icon */

    &::placeholder {
      color: var(--field-color-placeholder);
      font-weight: var(--text-body-medium-font-weight);
    }

    &:hover:not(:focus):not(:read-only) {
      border-color: var(--field-color-border-hover);
    }

    &:focus {
      border-color: var(--field-color-border-focus);
      outline: none;
    }

    &:read-only:focus {
      border-color: var(--field-color-border-hover);
    }

    &:disabled {
      background: var(--field-color-bg-disabled);
      /* color: var(--color-text-disabled); */
      border-color: var(--field-color-border-disabled);
    }
  }

  /* ——— Disabled calendar icon state ——— */
  .date-time-picker:has(input:disabled) .icon--calendar {
    color: var(--color-icon-disabled);
  }

  /* ——— Error state ——— */
  .date-time-picker--has-error .react-datepicker__input-container input {
    border-color: var(--field-color-border-error);
    border-width: var(--stroke-width-medium);
    padding: calc(var(--spacer-1) - 1px) calc(var(--spacer-2-5) - 1px);
    padding-right: calc(2.25rem - 1px);
  }

  /* ——— Appearance variants ——— */
  .date-time-picker__appearance--dayOnly .react-datepicker__month-container,
  .date-time-picker__appearance--monthOnly .react-datepicker__month-container {
    border-right: none;
  }

  .date-time-picker__input-wrapper {
    position: relative;
  }

  /* stylelint-disable-next-line plugin/no-max-width-media-query -- TODO: pre-existing; migrate to a mobile-first min-width query */
  @media (max-width: 768px) {
    .date-time-picker .react-datepicker {
      flex-direction: column;
    }

    .date-time-picker .react-datepicker__month-container {
      border-right: 0;
    }

    .date-time-picker .react-datepicker__time-container {
      align-self: stretch;
      width: auto;
      border-top: var(--stroke-width-small) solid var(--color-border);
    }

    .date-time-picker .react-datepicker__header--time {
      background-color: transparent;
      padding: var(--spacer-2) 0;
      border-bottom: none;
    }

    .date-time-picker
      .react-datepicker__time-container
      .react-datepicker__time
      .react-datepicker__time-box {
      height: var(--time-column-width);
      width: unset;

      > ul {
        height: var(--time-column-width);
      }
    }

    .date-time-picker
      .react-datepicker__navigation--next--with-time:not(
        .react-datepicker__navigation--next--with-today-button
      ) {
      right: 0;
    }

    .date-time-picker__input-wrapper .icon {
      top: 50%;
      transform: translateY(-50%);
    }
  }
}

