@layer payload-default {
  .drawer {
    display: flex;
    justify-content: flex-end;
    overflow: hidden;
    position: fixed;
    inset: 0;

    --gutter-h: var(--spacer-3);
    --gutter-v: var(--spacer-4);
  }

  @media (min-width: 768px) {
    .drawer {
      --gutter-h: var(--spacer-4);
    }
  }

  .drawer.drawer--is-open {
    visibility: visible;
  }

  .drawer__blur-bg {
    position: absolute;
    z-index: 1;
    inset: 0;
    opacity: 0;
    background: var(--color-drawer-backdrop);
  }

  .drawer__content {
    opacity: 0;
    position: relative;
    z-index: 2;
    width: clamp(600px, 40vw, 1080px);
    max-width: calc(100vw - var(--spacer-3));
    background-color: var(--color-bg);
    box-shadow: var(--elevation-400-menu-panel);
    container: drawer / inline-size;
    /* Animate the leftward shift when a nested drawer stacks on top. */
    transition: transform 100ms ease-out;
  }

  @media (min-width: 768px) {
    .drawer__content {
      max-width: 100vw;
    }
  }

  .drawer__content-children {
    position: relative;
    z-index: 1;
    overflow-x: clip;
    overflow-y: auto;
    height: 100%;
    display: flex;
    flex-direction: column;
  }

  /*
   * Content fades in on first render so the drawer body appears gracefully
   * instead of snapping in. Quick + soft, never blocky.
   */
  .drawer__fade-in {
    display: flex;
    flex-direction: column;
    flex: 1 0 auto;
    animation: drawer-content-fade-in 200ms ease-out both;
  }

  @keyframes drawer-content-fade-in {
    from {
      opacity: 0;
    }

    to {
      opacity: 1;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .drawer__fade-in {
      animation: none;
    }
  }

  .drawer--is-open .drawer__content,
  .drawer--is-open .drawer__blur-bg {
    opacity: 1;
  }

  /* Offset each ancestor drawer 16px left per drawer stacked on top of it. */
  .drawer--is-open .drawer__content {
    transform: translateX(calc(-1 * var(--drawer-layer-offset, 0px)));
  }

  .drawer__close {
