    align-items: center;
    justify-content: center;
    padding: 0;
    border: 0;
    border-radius: var(--radius-medium);
    background: transparent;
    color: var(--color-icon);
    cursor: pointer;
  }

  .edit-upload__reset:hover {
    background: var(--color-bg-secondary);
  }

  .edit-upload__reset:focus-visible {
    outline: var(--accessibility-outline);
  }

  .edit-upload__fieldset {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--spacer-2);
    padding-inline-start: var(--spacer-3);
    padding-inline-end: var(--spacer-2);
    padding-block: var(--spacer-1);
  }

  /* Draggable focal point */
  .edit-upload__draggable-container {
    position: absolute;
    inset: 0;
    pointer-events: none; /* let clicks pass through to the image/crop layer */
  }

  .edit-upload__draggable {
    position: absolute;
    pointer-events: all; /* only the handle itself is interactive */
  }

  .edit-upload__focalPoint {
    position: absolute;
    top: 50%;
    left: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    width: var(--spacer-5);
    height: var(--spacer-5);
    border-radius: 50%;
    background: var(--color-focal-point-backdrop);
    color: white;
    cursor: grab;
    transform: translate3d(-50%, -50%, 0);
    pointer-events: all;

    svg {
      width: 100%;
      height: 100%;
    }
  }

  /* stylelint-disable-next-line plugin/no-max-width-media-query -- TODO: pre-existing; migrate to a mobile-first min-width query */
  @media (max-width: 768px) {
    .edit-upload__content {
      flex-direction: column;
      min-height: unset;
    }

    .edit-upload__sidebar {
      width: 100%;
      border-inline-start: none;
      border-top: var(--stroke-width-small) solid var(--color-border);
    }
  }
}

elements/EditUpload/index.tsx:
'use client'

import type { UploadEdits } from 'payload'

import { useModal } from '@faceless-ui/modal'
import React, { useRef, useState } from 'react'
import ReactCrop from 'react-image-crop'

import { editDrawerSlug } from '../../elements/Upload/index.js'
import { NumberInput } from '../../fields/Number/index.js'
import { PlusIcon } from '../../icons/Plus/index.js'
import { ResetIcon } from '../../icons/Reset/index.js'
import { useTranslation } from '../../providers/Translation/index.js'
import { appendCacheTag } from '../../utilities/appendCacheTag.js'
import { Button } from '../Button/index.js'
import { DialogFooter, DialogHeader, DialogModal } from '../Dialog/index.js'
import './index.css'
import './library.css'

const baseClass = 'edit-upload'

type FocalPosition = {
  x: number
  y: number
}

export type EditUploadProps = {
  fileName: string
  fileSrc: string
  imageCacheTag?: false | string
  initialCrop?: UploadEdits['crop']
  initialFocalPoint?: FocalPosition
  onSave?: (uploadEdits: UploadEdits) => void
  showCrop?: boolean
  showFocalPoint?: boolean
}

const defaultCrop: UploadEdits['crop'] = {
  height: 100,
  unit: '%',
  width: 100,
  x: 0,
  y: 0,
}

export const EditUpload: React.FC<EditUploadProps> = ({
  fileName,
  fileSrc,
  imageCacheTag,
  initialCrop,
  initialFocalPoint,
  onSave,
  showCrop,
  showFocalPoint,
}) => {
  const { closeModal } = useModal()
  const { t } = useTranslation()

  const [crop, setCrop] = useState<UploadEdits['crop']>(() => ({
    ...defaultCrop,
    ...(initialCrop || {}),
  }))

  const defaultFocalPosition: FocalPosition = { x: 50, y: 50 }

  const [focalPosition, setFocalPosition] = useState<FocalPosition>(() => ({
    ...defaultFocalPosition,
    ...initialFocalPoint,
  }))

  const [checkBounds, setCheckBounds] = useState<boolean>(false)
  const [uncroppedPixelHeight, setUncroppedPixelHeight] = useState<number>(0)
  const [uncroppedPixelWidth, setUncroppedPixelWidth] = useState<number>(0)

  const focalWrapRef = useRef<HTMLDivElement | undefined>(undefined)
  const imageRef = useRef<HTMLImageElement | undefined>(undefined)
  const cropRef = useRef<HTMLDivElement | undefined>(undefined)

  const [imageLoaded, setImageLoaded] = useState<boolean>(false)

  const onImageLoad = (e) => {
    setUncroppedPixelHeight(e.currentTarget.naturalHeight)
    setUncroppedPixelWidth(e.currentTarget.naturalWidth)
    setImageLoaded(true)
  }

  const fineTuneCrop = ({ dimension, value }: { dimension: 'height' | 'width'; value: string }) => {
    const intValue = parseInt(value)
    if (Number.isNaN(intValue)) {
      return null
    }
    const percentage =
      100 * (intValue / (dimension === 'width' ? uncroppedPixelWidth : uncroppedPixelHeight))
    if (percentage <= 0 || percentage > 100) {
      return null
    }
    setCrop((prev) => ({ ...prev, [dimension]: percentage }))
  }

  const fineTuneFocalPosition = ({
    coordinate,
    value,
  }: {
    coordinate: 'x' | 'y'
    value: string
  }) => {
    const intValue = parseInt(value)
    if (intValue >= 0 && intValue <= 100) {
      setFocalPosition((prevPosition) => ({ ...prevPosition, [coordinate]: intValue }))
    }
  }

  const saveEdits = () => {
    if (typeof onSave === 'function') {
      onSave({
        crop: crop ? crop : undefined,
        focalPoint: focalPosition,
        heightInPixels: Math.round((crop.height / 100) * uncroppedPixelHeight),
        widthInPixels: Math.round((crop.width / 100) * uncroppedPixelWidth),
      })
    }
    closeModal(editDrawerSlug)
  }

  const onDragEnd = React.useCallback(({ x, y }) => {
    setFocalPosition({ x, y })
    setCheckBounds(false)
  }, [])

  const centerFocalPoint = () => {
    setFocalPosition({ x: 50, y: 50 })
  }

  const fileSrcToUse = fileSrc ? appendCacheTag(fileSrc, imageCacheTag) : undefined

  const cropWidthPx = ((crop.width / 100) * uncroppedPixelWidth).toFixed(0)
  const cropHeightPx = ((crop.height / 100) * uncroppedPixelHeight).toFixed(0)

  return (
    <DialogModal
      className={`${baseClass}__dialog`}
      closeOnBlur={false}
      size="large"
      slug={editDrawerSlug}
    >
      <DialogHeader showClose title={`${t('general:editing')} ${fileName}`} />
      <div className={`${baseClass}__body`}>
        <div className={`${baseClass}__content`}>
          {/* Canvas area */}
          <div className={`${baseClass}__crop`}>
            <div
              className={`${baseClass}__focal-wrapper`}
              ref={focalWrapRef}
              style={{ aspectRatio: `${uncroppedPixelWidth / uncroppedPixelHeight}` }}
            >
              {showCrop ? (
                <ReactCrop
                  ariaLabels={{
                    cropArea: t('upload:setCropArea'),
                    eDragHandle: t('upload:cropRight'),
                    nDragHandle: t('upload:cropTop'),
                    neDragHandle: t('upload:cropTopRight'),
                    nwDragHandle: t('upload:cropTopLeft'),
                    sDragHandle: t('upload:cropBottom'),
                    seDragHandle: t('upload:cropBottomRight'),
                    swDragHandle: t('upload:cropBottomLeft'),
                    wDragHandle: t('upload:cropLeft'),
                  }}
                  className={`${baseClass}__reactCrop`}
                  crop={crop}
                  onChange={(_, c) => setCrop(c)}
                  onComplete={() => setCheckBounds(true)}
                  renderSelectionAddon={() => (
                    <div className={`${baseClass}__crop-window`} ref={cropRef} />
                  )}
                >
                  <img
                    alt={t('upload:setCropArea')}
                    onLoad={onImageLoad}
                    ref={imageRef}
                    src={fileSrcToUse}
                  />
                </ReactCrop>
              ) : (
                <img
                  alt={t('upload:setFocalPoint')}
                  onLoad={onImageLoad}
                  ref={imageRef}
                  src={fileSrcToUse}
                />
              )}
              {showFocalPoint && (
                <DraggableElement
                  boundsRef={showCrop ? cropRef : imageRef}
                  checkBounds={showCrop ? checkBounds : false}
                  className={`${baseClass}__focalPoint`}
                  containerRef={focalWrapRef}
                  initialPosition={focalPosition}
                  onDragEnd={onDragEnd}
                  setCheckBounds={showCrop ? setCheckBounds : false}
                >
                  <PlusIcon />
                </DraggableElement>
              )}
            </div>
          </div>

          {/* Sidebar */}
          {(showCrop || showFocalPoint) && (
            <div className={`${baseClass}__sidebar`}>
              {showCrop && (
                <div className={`${baseClass}__section`}>
                  <div className={`${baseClass}__section-header`}>
                    <h3 className={`${baseClass}__section-title`}>{t('upload:crop')}</h3>
                    <button
                      aria-label={`${t('general:reset')}: ${t('upload:crop')}`}
                      className={`${baseClass}__reset`}
                      onClick={() => setCrop({ height: 100, unit: '%', width: 100, x: 0, y: 0 })}
                      type="button"
                    >
                      <ResetIcon />
                    </button>
                  </div>
                  <div className={`${baseClass}__fieldset`}>
                    <NumberInput
                      ariaLabel={t('upload:width')}
                      onChange={(e) => fineTuneCrop({ dimension: 'width', value: e.target.value })}
                      path="cropWidth"
                      prefix="W"
                      readOnly={!imageLoaded}
                      size="medium"
                      value={Number(cropWidthPx)}
                    />
                    <NumberInput
                      ariaLabel={t('upload:height')}
                      onChange={(e) => fineTuneCrop({ dimension: 'height', value: e.target.value })}
                      path="cropHeight"
                      prefix="H"
                      readOnly={!imageLoaded}
                      size="medium"
                      value={Number(cropHeightPx)}
                    />
                  </div>
                </div>
              )}

              {showFocalPoint && (
                <div className={`${baseClass}__section`}>
                  <div className={`${baseClass}__section-header`}>
                    <h3 className={`${baseClass}__section-title`}>{t('upload:focalPoint')}</h3>
                    <button
                      aria-label={`${t('general:reset')}: ${t('upload:focalPoint')}`}
                      className={`${baseClass}__reset`}
                      onClick={centerFocalPoint}
                      type="button"
                    >
                      <ResetIcon />
                    </button>
                  </div>
                  <div className={`${baseClass}__fieldset`}>
                    <NumberInput
                      ariaLabel={`${t('upload:focalPoint')} X`}
                      max={100}
                      min={0}
                      onChange={(e) =>
                        fineTuneFocalPosition({ coordinate: 'x', value: e.target.value })
                      }
                      path="focalX"
                      prefix="X"
                      size="medium"
                      suffix="%"
                      value={Math.round(focalPosition.x)}
                    />
                    <NumberInput
                      ariaLabel={`${t('upload:focalPoint')} Y`}
                      max={100}
                      min={0}
                      onChange={(e) =>
                        fineTuneFocalPosition({ coordinate: 'y', value: e.target.value })
                      }
                      path="focalY"
                      prefix="Y"
                      size="medium"
                      suffix="%"
                      value={Math.round(focalPosition.y)}
                    />
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
      <DialogFooter>
        <Button
          aria-label={t('general:cancel')}
          buttonStyle="secondary"
          onClick={() => closeModal(editDrawerSlug)}
        >
          {t('general:cancel')}
        </Button>
        <Button
          aria-label={t('general:applyChanges')}
          buttonStyle="primary"
          disabled={!imageLoaded}
          onClick={saveEdits}
        >
          {t('general:applyChanges')}
        </Button>
      </DialogFooter>
    </DialogModal>
  )
}

const DraggableElement = ({
  boundsRef,
  checkBounds,
  children,
  className,
  containerRef,
  initialPosition = { x: 50, y: 50 },
  onDragEnd,
  setCheckBounds,
}) => {
  const { t } = useTranslation()

  const [position, setPosition] = useState({ x: initialPosition.x, y: initialPosition.y })
  const [isDragging, setIsDragging] = useState(false)
  const dragRef = useRef<HTMLButtonElement | undefined>(undefined)
  // Keep a ref to the latest position so global mouseup handler can read it without a stale closure
  const positionRef = useRef(position)
  positionRef.current = position

  const getCoordinates = React.useCallback(
    (mouseX: number, mouseY: number) => {
      const containerRect = containerRef.current.getBoundingClientRect()
      const x = ((mouseX - containerRect.left) / containerRect.width) * 100
      const y = ((mouseY - containerRect.top) / containerRect.height) * 100
      return { x: Math.max(0, Math.min(100, x)), y: Math.max(0, Math.min(100, y)) }
    },
    [containerRef],
  )

  const handleMouseDown = (event) => {
    event.preventDefault()
    setIsDragging(true)
  }

  const handleKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (event.altKey || event.ctrlKey || event.metaKey || isDragging) {
      return
    }
    const step = event.shiftKey ? 10 : 1
    let { x, y } = positionRef.current

    switch (event.key) {
      case 'ArrowDown':
        y += step
        break
      case 'ArrowLeft':
        x -= step
        break
      case 'ArrowRight':
        x += step
        break
      case 'ArrowUp':
        y -= step
        break
      default:
        return
    }

    event.preventDefault()
    event.stopPropagation()
    const nextPosition = {
      x: Math.max(0, Math.min(100, x)),
      y: Math.max(0, Math.min(100, y)),
    }

    positionRef.current = nextPosition
    setPosition(nextPosition)
    onDragEnd(nextPosition)
  }

  // Attach global listeners while dragging — this ensures events fire even when
  // the cursor leaves the focal wrapper area during a fast drag
  React.useEffect(() => {
    if (!isDragging) {
      return
    }

    const handleMove = (e: MouseEvent) => {
      if (!containerRef.current) {
        return
      }
      const { x, y } = getCoordinates(e.clientX, e.clientY)
      setPosition({ x, y })
    }

    const handleUp = () => {
      setIsDragging(false)
      onDragEnd(positionRef.current)
    }

    document.addEventListener('mousemove', handleMove)
    document.addEventListener('mouseup', handleUp)

    return () => {
      document.removeEventListener('mousemove', handleMove)
      document.removeEventListener('mouseup', handleUp)
    }
  }, [isDragging, getCoordinates, onDragEnd, containerRef])

  // Re-check position when crop changes (the crop window may have moved)
  React.useEffect(() => {
    if (isDragging || !checkBounds || !dragRef.current) {
      return
    }
    const { height, left, top, width } = dragRef.current.getBoundingClientRect()
    const { x, y } = getCoordinates(left + width / 2, top + height / 2)
    onDragEnd({ x, y })
    setPosition({ x, y })
    setCheckBounds(false)
  }, [getCoordinates, isDragging, checkBounds, setCheckBounds, onDragEnd])

  React.useEffect(() => {
    setPosition({ x: initialPosition.x, y: initialPosition.y })
  }, [initialPosition.x, initialPosition.y])

  return (
    <div className={`${baseClass}__draggable-container`}>
      <button
        aria-keyshortcuts="ArrowLeft ArrowRight ArrowUp ArrowDown Shift+ArrowLeft Shift+ArrowRight Shift+ArrowUp Shift+ArrowDown"
        aria-label={t('upload:setFocalPoint')}
        className={[`${baseClass}__draggable`, className].filter(Boolean).join(' ')}
        onKeyDown={handleKeyDown}
        onMouseDown={handleMouseDown}
        ref={dragRef}
        style={{ left: `${position.x}%`, top: `${position.y}%` }}
        type="button"
      >
        {children}
      </button>
    </div>
  )
}

elements/EditUpload/library.css:
/* CSS manually copied into the payload-default layer from the react-image-crop library */
/* see: /node_modules/react-image-crop/dist/ReactCrop.css */

@layer payload-default {
  .ReactCrop {
    /* Thickness of the corner brackets and edge grab handles. */
    --crop-handle-thickness: 5px;
    position: relative;
    display: inline-block;
    cursor: crosshair;
    overflow: hidden;
    max-width: 100%;
  }

  .ReactCrop *,
  .ReactCrop *:before,
  .ReactCrop *:after {
    box-sizing: border-box;
  }

  .ReactCrop--disabled,
  .ReactCrop--locked {
    cursor: inherit;
  }

  .ReactCrop__child-wrapper {
    max-height: inherit;
  }

  .ReactCrop__child-wrapper > img,
  .ReactCrop__child-wrapper > video {
    display: block;
    max-width: 100%;
    max-height: inherit;
  }

  .ReactCrop:not(.ReactCrop--disabled) .ReactCrop__child-wrapper > img,
  .ReactCrop:not(.ReactCrop--disabled) .ReactCrop__child-wrapper > video {
    touch-action: none;
  }

  .ReactCrop:not(.ReactCrop--disabled) .ReactCrop__crop-selection {
    touch-action: none;
  }

  .ReactCrop__crop-selection {
    --crop-ants-speed: 0s;
    position: absolute;
    top: 0;
    left: 0;
    transform: translateZ(0);
    cursor: move;
    box-shadow: 0 0 0 9999em rgba(0, 0, 0, 0.5);
    animation: marching-ants var(--crop-ants-speed) linear infinite;
    background-image:
      linear-gradient(to right, transparent 50%, var(--color-border-selected) 50%),
      linear-gradient(to right, transparent 50%, var(--color-border-selected) 50%),
      linear-gradient(to bottom, transparent 50%, var(--color-border-selected) 50%),
      linear-gradient(to bottom, transparent 50%, var(--color-border-selected) 50%);
    background-size:
      var(--spacer-2) var(--stroke-width-small),
      var(--spacer-2) var(--stroke-width-small),
      var(--stroke-width-small) var(--spacer-2),
      var(--stroke-width-small) var(--spacer-2);
    background-position:
      0 0,
      0 100%,
      0 0,
      100% 0;
    background-repeat: repeat-x, repeat-x, repeat-y, repeat-y;
  }

  @keyframes marching-ants {
    to {
      background-position:
        10px 0,
        -10px 100%,
        0 -10px,
        100% 10px;
    }
  }

  .ReactCrop--disabled .ReactCrop__crop-selection {
    cursor: inherit;
  }

  .ReactCrop--circular-crop .ReactCrop__crop-selection {
    border-radius: 50%;
  }

  .ReactCrop__crop-selection:focus-visible {
    outline: var(--stroke-width-medium) solid var(--color-border-selected);
    outline-offset: calc(var(--stroke-width-medium) * -1);
  }

  .ReactCrop--invisible-crop .ReactCrop__crop-selection {
    display: none;
  }

  .ReactCrop__rule-of-thirds-vt:before,
  .ReactCrop__rule-of-thirds-vt:after,
  .ReactCrop__rule-of-thirds-hz:before,
  .ReactCrop__rule-of-thirds-hz:after {
    content: '';
    display: block;
    position: absolute;
    background-color: rgba(255, 255, 255, 0.4);
  }

  .ReactCrop__rule-of-thirds-vt:before,
  .ReactCrop__rule-of-thirds-vt:after {
    width: 1px;
    height: 100%;
  }

  .ReactCrop__rule-of-thirds-vt:before {
    left: 33.3333333333%;
  }

  .ReactCrop__rule-of-thirds-vt:after {
    left: 66.6666666667%;
  }

  .ReactCrop__rule-of-thirds-hz:before,
  .ReactCrop__rule-of-thirds-hz:after {
    width: 100%;
    height: 1px;
  }

  .ReactCrop__rule-of-thirds-hz:before {
    top: 33.3333333333%;
  }

  .ReactCrop__rule-of-thirds-hz:after {
    top: 66.6666666667%;
  }

  .ReactCrop__drag-handle {
    position: absolute;
  }

  .ReactCrop__drag-handle:after {
    position: absolute;
    content: '';
    display: block;
    background-color: var(--color-border-selected);
    outline: 1px solid transparent;
  }

  .ReactCrop .ReactCrop__drag-handle:focus-visible:after {
    outline: var(--stroke-width-medium) solid var(--color-border-selected-strong);
    outline-offset: var(--stroke-width-small);
  }

  .ReactCrop .ord-nw {
    top: 0;
    left: 0;
    margin-top: -5px;
    margin-left: -5px;
    cursor: nw-resize;
  }

  .ReactCrop .ord-nw:after {
    top: 0;
    left: 0;
  }

  .ReactCrop .ord-n {
    top: 0;
    left: 50%;
    margin-top: -5px;
    margin-left: -5px;
    cursor: n-resize;
  }

  .ReactCrop .ord-n:after {
    top: 0;
  }

  .ReactCrop .ord-ne {
    top: 0;
    right: 0;
    margin-top: -5px;
    margin-right: -5px;
    cursor: ne-resize;
  }

  .ReactCrop .ord-ne:after {
    top: 0;
    right: 0;
  }

  .ReactCrop .ord-e {
    top: 50%;
    right: 0;
    margin-top: -5px;
    margin-right: -5px;
    cursor: e-resize;
  }

  .ReactCrop .ord-e:after {
    right: 0;
  }

  .ReactCrop .ord-se {
    bottom: 0;
    right: 0;
    margin-bottom: -5px;
    margin-right: -5px;
    cursor: se-resize;
  }

  .ReactCrop .ord-se:after {
    bottom: 0;
    right: 0;
  }

  .ReactCrop .ord-s {
    bottom: 0;
    left: 50%;
    margin-bottom: -5px;
    margin-left: -5px;
    cursor: s-resize;
  }

  .ReactCrop .ord-s:after {
    bottom: 0;
  }

  .ReactCrop .ord-sw {
    bottom: 0;
    left: 0;
    margin-bottom: -5px;
    margin-left: -5px;
    cursor: sw-resize;
  }

  .ReactCrop .ord-sw:after {
    bottom: 0;
    left: 0;
  }

  .ReactCrop .ord-w {
    top: 50%;
    left: 0;
    margin-top: -5px;
    margin-left: -5px;
    cursor: w-resize;
  }

  .ReactCrop .ord-w:after {
    left: 0;
  }

  /* L-shaped corner handles (matches Figma "Crop handle") */
  .ReactCrop .ord-nw:after,
  .ReactCrop .ord-ne:after,
  .ReactCrop .ord-se:after,
  .ReactCrop .ord-sw:after {
    width: 12px;
    height: 12px;
    background-color: transparent;
    border: 0;
  }

  .ReactCrop .ord-nw:after {
    top: 5px;
    left: 5px;
    border-top: var(--crop-handle-thickness) solid var(--color-border-selected);
    border-left: var(--crop-handle-thickness) solid var(--color-border-selected);
  }

  .ReactCrop .ord-ne:after {
    top: 5px;
    right: 5px;
    border-top: var(--crop-handle-thickness) solid var(--color-border-selected);
    border-right: var(--crop-handle-thickness) solid var(--color-border-selected);
  }

  .ReactCrop .ord-se:after {
    bottom: 5px;
    right: 5px;
    border-bottom: var(--crop-handle-thickness) solid var(--color-border-selected);
    border-right: var(--crop-handle-thickness) solid var(--color-border-selected);
  }

  .ReactCrop .ord-sw:after {
    bottom: 5px;
    left: 5px;
    border-bottom: var(--crop-handle-thickness) solid var(--color-border-selected);
    border-left: var(--crop-handle-thickness) solid var(--color-border-selected);
  }

  /* Edge midpoint handles (slim bars) */
  .ReactCrop .ord-n:after,
  .ReactCrop .ord-s:after {
    width: 12px;
    height: var(--crop-handle-thickness);
    left: -1px;
    border-radius: 1px;
  }

  .ReactCrop .ord-n:after {
    top: 5px;
  }

  .ReactCrop .ord-s:after {
    bottom: 5px;
