'use client'
import React, { useRef } from 'react'

import { useElementHeightVariable } from '../../../hooks/useElementHeightVariable.js'
import { ChevronIcon } from '../../../icons/Chevron/index.js'
import { CropIcon } from '../../../icons/Crop/index.js'
import { DownloadIcon } from '../../../icons/Download/index.js'
import { LinkIcon } from '../../../icons/Link/index.js'
import { NewTabIcon } from '../../../icons/NewTab/index.js'
import { SwapIcon } from '../../../icons/Swap/index.js'
import { useTranslation } from '../../../providers/Translation/index.js'
import { Button } from '../../Button/index.js'
import { CopyToClipboard } from '../../CopyToClipboard/index.js'
import { Popup } from '../../Popup/index.js'
import * as PopupList from '../../Popup/PopupButtonList/index.js'
import './index.css'

const baseClass = 'file-toolbar'

type Props = {
  readonly filename: string
  readonly fileSrc?: null | string
  readonly fileUrl?: null | string
  readonly hideRemoveFile?: boolean
  readonly isAdjustable?: boolean
  readonly onEditImage?: () => void
  readonly onReplace?: () => void
}

export const FileToolbar: React.FC<Props> = ({
  filename,
  fileSrc,
  fileUrl,
  hideRemoveFile,
  isAdjustable,
  onEditImage,
  onReplace,
}) => {
  const { t } = useTranslation()
  const ref = useRef<HTMLDivElement>(null)
  useElementHeightVariable({ cssVar: '--file-toolbar-height', ref })

  return (
    <div className={baseClass} ref={ref}>
      <div className={`${baseClass}__left`}>
        {hideRemoveFile ? (
          <span className={`${baseClass}__filename-btn ${baseClass}__filename-btn--static`}>
            <span className={`${baseClass}__filename-text`}>{filename}</span>
          </span>
        ) : (
          <Popup
            button={
              <span className={`${baseClass}__filename-btn`}>
                <span className={`${baseClass}__filename-text`}>{filename}</span>
                <ChevronIcon size={16} />
              </span>
            }
            buttonType="custom"
            horizontalAlign="left"
            popupType="menu"
            portalClassName={`${baseClass}__filename-popup`}
            size="fit-content"
            verticalAlign="bottom"
          >
            <PopupList.MenuItem>
              <PopupList.Button icon={<SwapIcon />} onClick={onReplace}>
                {t('upload:replaceFile')}
              </PopupList.Button>
            </PopupList.MenuItem>
          </Popup>
        )}
      </div>

      <div className={`${baseClass}__right`}>
        {fileUrl && (
          <CopyToClipboard
            defaultMessage={t('upload:copyLinkToFile')}
            icon={<LinkIcon />}
            value={fileUrl}
          />
        )}
        {isAdjustable && (
          <Button
            aria-label={t('upload:editImage')}
            buttonStyle="ghost"
            icon={<CropIcon size={24} />}
            margin={false}
            onClick={onEditImage}
            round={false}
            tooltip={t('upload:editImage')}
          />
        )}
        {fileSrc && (
          <a
            aria-label={t('fields:openInNewTab')}
            className={`${baseClass}__icon-link`}
            href={fileSrc}
            rel="noopener noreferrer"
            target="_blank"
            title={t('fields:openInNewTab')}
          >
            <NewTabIcon size={24} />
          </a>
        )}
        {fileSrc && (
          <a
            aria-label={t('upload:download')}
            className={`${baseClass}__icon-link`}
            download={filename}
            href={fileSrc}
            title={t('upload:download')}
          >
            <DownloadIcon size={24} />
          </a>
        )}
      </div>
    </div>
  )
}

elements/FileManager/index.css:
@layer payload-default {
  .file-manager {
    --file-fields-max-width: 600px;
    position: relative;
    align-self: stretch;
    width: 100%;
    margin-bottom: 0;
    border-radius: 0;
    background: var(--color-bg-secondary);
    min-height: 400px;
    border-bottom: var(--stroke-width-small) solid var(--color-border);

    .dropzone {
      border: none;
      border-radius: 0;
    }
  }

  .file-manager__panel {
    position: static;
    height: auto;
    min-height: 400px;
    display: flex;
    flex-direction: column;
    /* Visible so the mini carousel can grow past the panel to fill the area left behind as the
       app/doc headers scroll away (see MiniCarousel). */
    overflow: visible;
  }

  .file-manager__content {
    display: flex;
    flex-direction: column;
    /* flex-basis: auto (not 0) so this sizes to its content when the panel's height is auto
       (stacked layout) instead of collapsing — flex-basis 0 only makes sense when the panel
       has a definite height to grow into (see the min-width override below). */
    flex: 1 1 auto;
    overflow: visible;
  }

  .file-manager__upload {
    display: flex;
    flex: 1 0 0;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--spacer-4);
    padding: var(--spacer-4) var(--gutter-h);
    position: relative;
  }

  /* Fill the whole upload area so a file can be dropped onto any part of the file manager,
     not just the band occupied by the dropzone's buttons. */
  .file-manager__upload .dropzone {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .file-manager__upload .file-manager__remove {
    position: absolute;
    top: var(--gutter-h);
    right: var(--gutter-h);
    margin: 0;
    z-index: 1;
  }

  /* Preview of a freshly-selected (not-yet-saved) file. Capped so large media stays contained;
     the definite height lets the PDF iframe / video / image fill it. */
  .file-manager__selected-preview {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    max-width: 420px;
    height: min(50dvh, 320px);
    overflow: hidden;
    border-radius: var(--radius-small);
  }

  /* Audio is just a player bar — no tall box needed. */
  .file-manager__selected-preview--audio {
    height: auto;
  }

  .file-manager__selected-preview .thumbnail img,
  .file-manager__selected-preview .thumbnail svg {
    object-fit: contain;
  }

  .file-manager__file-adjustments {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: var(--spacer-2);
    margin-bottom: var(--spacer-2);
  }

  .file-manager__selected-meta {
    color: var(--color-text-tertiary);
    font-size: var(--text-body-small-font-size);
    line-height: var(--text-body-small-line-height);
  }

  @container edit-main (min-width: 1024px) {
    .file-manager {
      min-height: 100px;
      border-bottom: none;
    }

    .file-manager__upload {
      padding: var(--spacer-4);
    }

    .file-manager__file-adjustments {
      max-width: var(--file-fields-max-width);
    }

    .file-manager__panel {
      position: sticky;
      top: var(--doc-controls-height);
      /* Scroll-driven: grow height as the app header and doc header scroll away, matching the
         extra space they free up. Mirrors the MiniCarousel approach. Falls back to static height. */
      height: calc(
        100dvh - var(--app-header-height) - var(--doc-controls-height) - var(--doc-header-height)
      );
    }

    .file-manager__content {
      flex-direction: row;
      min-height: 0;
    }
  }
}

elements/FileManager/index.tsx:
'use client'
import type { SanitizedCollectionConfig, UploadEdits } from 'payload'

import { useModal } from '@faceless-ui/modal'
import { formatFilesize, isImage, validateMimeType } from 'payload/shared'
import React, { Fragment, useCallback, useEffect, useState } from 'react'
import { toast } from 'sonner'

import { FieldError } from '../../fields/FieldError/index.js'
import { fieldBaseClass } from '../../fields/shared/index.js'
import { TextInput } from '../../fields/Text/Input.js'
import { useForm } from '../../forms/Form/index.js'
import { useField } from '../../forms/useField/index.js'
import { useDocumentInfo } from '../../providers/DocumentInfo/index.js'
import { EditDepthProvider } from '../../providers/EditDepth/index.js'
import { useTranslation } from '../../providers/Translation/index.js'
import { useUploadControls } from '../../providers/UploadControls/index.js'
import { useUploadEdits } from '../../providers/UploadEdits/index.js'
import { Button } from '../Button/index.js'
import { Drawer } from '../Drawer/index.js'
import { Dropzone } from '../Dropzone/index.js'
import { EditUpload } from '../EditUpload/index.js'
import { PreviewSizes } from '../PreviewSizes/index.js'
import { Thumbnail } from '../Thumbnail/index.js'
import { getEditorFileSrc } from '../Upload/getEditorFileSrc.js'
import { editDrawerSlug, sizePreviewSlug } from '../Upload/index.js'
import { UploadFromURLModal } from '../Upload/UploadFromURLModal/index.js'
import { usePasteFromClipboard } from '../Upload/usePasteFromClipboard.js'
import { useUploadFromUrl } from '../Upload/useUploadFromUrl.js'
import { UploadDropzoneContent } from '../UploadDropzoneContent/index.js'
import { AudioPreview } from './FilePreview/AudioPreview/index.js'
import { FilePreview } from './FilePreview/index.js'
import { PdfPreview } from './FilePreview/PdfPreview/index.js'
import { VideoPreview } from './FilePreview/VideoPreview/index.js'
import { FileToolbar } from './FileToolbar/index.js'
import './index.css'

const baseClass = 'file-manager'

export type FileManagerProps = {
  readonly collectionSlug: string
  readonly initialState?: import('payload').FormState
  /**
   * When provided, upload edits are sourced from these props instead of the `useUploadEdits`
   * context. The bulk upload drawer uses this to drive per-file edits from its FormsManager.
   */
  readonly resetUploadEdits?: () => void
  readonly updateUploadEdits?: (args: UploadEdits) => void
  readonly uploadConfig: Omit<SanitizedCollectionConfig['upload'], 'uploadInstructions'>
  readonly UploadControls?: React.ReactNode
  readonly uploadEdits?: UploadEdits
  readonly UploadFilePreview?: React.ReactNode
}

export const FileManager: React.FC<FileManagerProps> = ({
  collectionSlug,
  initialState,
  resetUploadEdits: resetUploadEditsFromProps,
  updateUploadEdits: updateUploadEditsFromProps,
  uploadConfig,
  UploadControls,
  uploadEdits: uploadEditsFromProps,
  UploadFilePreview,
}) => {
  const { openModal } = useModal()
  const { t } = useTranslation()
  const { setModified } = useForm()
  const { data } = useDocumentInfo()
  const validate = useCallback(
    (file: File | null | undefined) => {
      if (!file && file !== undefined) {
        return 'A file is required.'
      }
      if (file && (!file.name || file.name === '')) {
        return 'A file name is required.'
      }
      if (
        file instanceof File &&
        uploadConfig.mimeTypes?.length &&
        !validateMimeType(file.type, uploadConfig.mimeTypes)
      ) {
        return t('error:invalidFileType')
      }
      return true
    },
    [t, uploadConfig.mimeTypes],
  )
  const { errorMessage, setValue, showError, value } = useField<File>({
    path: 'file',
    validate,
  })
  const {
    setUploadControlFile,
    setUploadControlFileName,
    setUploadControlFileUrl,
    uploadControlFile,
    uploadControlFileUrl,
  } = useUploadControls()
  const uploadEditsContext = useUploadEdits()
  const resetUploadEdits = resetUploadEditsFromProps ?? uploadEditsContext.resetUploadEdits
  const updateUploadEdits = updateUploadEditsFromProps ?? uploadEditsContext.updateUploadEdits
  const uploadEdits = uploadEditsFromProps ?? uploadEditsContext.uploadEdits

  const [fileSrc, setFileSrc] = useState<null | string>(null)
  const [removedFile, setRemovedFile] = useState(false)
  const [filename, setFilename] = useState<string>(value?.name || '')
  const [selectedSize, setSelectedSize] = useState<null | string>(null)

  const acceptMimeTypes = uploadConfig.mimeTypes?.join(', ')
  const imageCacheTag = uploadConfig?.cacheTags && data?.updatedAt

  const hasVariants = uploadConfig?.variants?.length > 0
  const hasImageAdjustments = Boolean(uploadConfig?.hasImageAdjustments)
  const focalPointEnabled = uploadConfig?.focalPoint === true
  const { crop: showCrop = true, focalPoint = true } = uploadConfig
  const showFocalPoint = focalPoint && (hasVariants || hasImageAdjustments || focalPointEnabled)

  const selectedSizeData = selectedSize
    ? (data?.variants?.[selectedSize] as Record<string, unknown>)
    : null
  const sidePanelFileSrc = (selectedSizeData?.url ?? data?.thumbnailURL ?? data?.url ?? null) as
    | null
    | string
  const sidePanelMimeType = data?.mimeType as string | undefined
  const fileTypeIsAdjustable =
    !!sidePanelMimeType &&
    isImage(sidePanelMimeType) &&
    sidePanelMimeType !== 'image/svg+xml' &&
    sidePanelMimeType !== 'image/jxl'

  const renameFile = (fileToChange: File, newName: string): File =>
    new File([fileToChange], newName, {
      type: fileToChange.type,
      lastModified: fileToChange.lastModified,
    })

  const handleFileChange = useCallback(
    ({ file, isNewFile = true }: { file: File | null; isNewFile?: boolean }) => {
      if (
        file instanceof File &&
        uploadConfig.mimeTypes?.length &&
        !validateMimeType(file.type, uploadConfig.mimeTypes)
      ) {
        toast.error(t('error:invalidFileType'))
        return
      }
      if (isNewFile && file instanceof File) {
        setFileSrc(URL.createObjectURL(file))
      }
      setValue(file)
      setUploadControlFileUrl('')
      setUploadControlFileName(null)
      setUploadControlFile(null)
    },
    [
      setValue,
      setUploadControlFile,
      setUploadControlFileName,
      setUploadControlFileUrl,
      t,
      uploadConfig.mimeTypes,
    ],
  )

  const handleFileNameChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const updatedFileName = e.target.value
      if (value) {
        handleFileChange({ file: renameFile(value, updatedFileName), isNewFile: false })
        setFilename(updatedFileName)
      }
    },
    [handleFileChange, value],
  )

  const handleFileSelection = useCallback(
    (files: FileList) => handleFileChange({ file: files?.[0] }),
    [handleFileChange],
  )

  const handleFileFetchedFromUrl = useCallback(
    (file: File) => handleFileChange({ file }),
    [handleFileChange],
  )

  const { fileUrl, handleUrlSubmit, isValidUrl, setFileUrl } = useUploadFromUrl({
    collectionSlug,
    onFileFetched: handleFileFetchedFromUrl,
    uploadConfig,
  })

  const handlePasteFromClipboard = usePasteFromClipboard({
    handleFileSelection,
    handleUrlSubmit,
    setFileUrl,
    uploadConfig,
  })

  const handleFileRemoval = useCallback(() => {
    setRemovedFile(true)
    handleFileChange({ file: null })
    setFileSrc('')
    setFileUrl('')
    setSelectedSize(null)
    resetUploadEdits()
    setUploadControlFileUrl('')
    setUploadControlFileName(null)
    setUploadControlFile(null)
  }, [
    handleFileChange,
    resetUploadEdits,
    setFileUrl,
    setUploadControlFile,
    setUploadControlFileName,
    setUploadControlFileUrl,
  ])

  const onEditsSave = useCallback(
    (args: UploadEdits) => {
      setModified(true)
      updateUploadEdits(args)
    },
    [setModified, updateUploadEdits],
  )

  // Reset states for when replacing the file with a new upload
  useEffect(() => {
    setSelectedSize(null)
    setRemovedFile(false)
    setFileSrc('')
  }, [data?.url, data?.filename])

  useEffect(() => {
    if (initialState?.file?.value instanceof File) {
      setFileSrc(URL.createObjectURL(initialState.file.value))
      setRemovedFile(false)
    }
  }, [initialState])

  useEffect(() => {
    return () => {
      if (fileSrc?.startsWith('blob:')) {
        URL.revokeObjectURL(fileSrc)
      }
    }
  }, [fileSrc])

  useEffect(() => {
    const handleControlFileUrl = async () => {
      if (uploadControlFileUrl) {
        setFileUrl(uploadControlFileUrl)
        await handleUrlSubmit()
      }
    }
    void handleControlFileUrl()
  }, [uploadControlFileUrl, handleUrlSubmit, setFileUrl])

  useEffect(() => {
    if (uploadControlFile) {
      handleFileChange({ file: uploadControlFile })
    }
  }, [uploadControlFile, handleFileChange])

  // Preview a freshly-selected (not-yet-saved) file from its local object URL, so video/audio/PDF
  // are playable/viewable just like images. Sizing is capped in CSS so large files stay contained.
  const renderSelectedFilePreview = (src: string) => {
    const fileType = value?.type ?? ''

    if (fileType.startsWith('video/')) {
      return (
        <div className={`${baseClass}__selected-preview`}>
          <VideoPreview fileSrc={src} />
        </div>
      )
    }

    if (fileType.startsWith('audio/')) {
      return (
        <div className={`${baseClass}__selected-preview ${baseClass}__selected-preview--audio`}>
          <AudioPreview fileSrc={src} />
        </div>
      )
    }

    if (fileType === 'application/pdf') {
      return (
        <div className={`${baseClass}__selected-preview`}>
          <PdfPreview fileSrc={src} title={value?.name} />
        </div>
      )
    }

    return (
      <div className={`${baseClass}__selected-preview`}>
        <Thumbnail
          collectionSlug={collectionSlug}
          fileSrc={isImage(fileType) ? src : null}
          size="expand"
        />
      </div>
    )
  }

  const drawers = (
    <Fragment>
      {(value || data?.filename) && (
        <EditDepthProvider>
          <EditUpload
            fileName={value?.name || (data?.filename as string)}
            fileSrc={getEditorFileSrc({ data, fileSrc, hasSelectedFile: Boolean(value) })}
            imageCacheTag={imageCacheTag}
            initialCrop={uploadEdits?.crop ?? undefined}
            initialFocalPoint={{
              x: uploadEdits?.focalPoint?.x || (data?.focalX as number) || 50,
              y: uploadEdits?.focalPoint?.y || (data?.focalY as number) || 50,
            }}
            onSave={onEditsSave}
            showCrop={showCrop}
            showFocalPoint={showFocalPoint}
          />
        </EditDepthProvider>
      )}
      {data && hasVariants && (
        <Drawer
          className={`${baseClass}__preview-drawer`}
          hoverTitle
          slug={sizePreviewSlug}
          title={t('upload:sizesFor', { label: data.filename })}
        >
          <PreviewSizes doc={data} imageCacheTag={imageCacheTag} uploadConfig={uploadConfig} />
        </Drawer>
      )}
      {uploadConfig?.pasteURL !== false && (
        <UploadFromURLModal
          fileUrl={fileUrl}
          handleUrlSubmit={handleUrlSubmit}
          isValidUrl={isValidUrl}
          setFileUrl={setFileUrl}
        />
      )}
    </Fragment>
  )

  // Hide the create file input when the collection opts out of it (unless the user has explicitly
  // removed an existing file or already selected a new one).
  const showUploadInput = Boolean(value) || removedFile || !uploadConfig?.hideFileInputOnCreate

  return (
    <div className={[fieldBaseClass, baseClass].filter(Boolean).join(' ')}>
      <FieldError message={errorMessage} path="filename" showError={showError} />
      <div className={`${baseClass}__panel`}>
        {data?.filename && !removedFile && (
          <FileToolbar
            filename={data.filename as string}
            fileSrc={sidePanelFileSrc}
            fileUrl={data?.url as string}
            hideRemoveFile={uploadConfig?.hideRemoveFile}
            isAdjustable={fileTypeIsAdjustable}
            onEditImage={() => openModal(editDrawerSlug)}
            onReplace={handleFileRemoval}
          />
        )}
        <div className={`${baseClass}__content`}>
          {data?.filename && !removedFile ? (
            <FilePreview
              collectionSlug={collectionSlug}
              data={data as Record<string, unknown>}
              imageCacheTag={imageCacheTag}
              selectedSize={selectedSize}
              selectedSizeData={selectedSizeData}
              setSelectedSize={setSelectedSize}
              uploadConfig={uploadConfig}
              UploadFilePreview={UploadFilePreview}
            />
          ) : showUploadInput ? (
            <div className={`${baseClass}__upload`}>
              {!value && removedFile && data?.filename && (
                <Button
                  aria-label={t('general:cancel')}
                  buttonStyle="secondary"
                  className={`${baseClass}__remove`}
                  icon="x"
                  onClick={() => setRemovedFile(false)}
                  round
                  tooltip={t('general:cancel')}
                />
              )}
              {!value && (
                <Dropzone onChange={handleFileSelection}>
                  <UploadDropzoneContent
                    acceptMimeTypes={acceptMimeTypes}
                    extraControls={UploadControls}
                    onFilesSelected={handleFileSelection}
                    onPasteFromClipboard={handlePasteFromClipboard}
                    pasteButtonClassName={`${baseClass}__pasteFromClipboard`}
                    pasteTooltip={t('upload:pasteURL')}
                  />
                </Dropzone>
              )}
              {value && fileSrc && (
                <Fragment>
                  <Button
                    aria-label={t('general:cancel')}
                    buttonStyle="secondary"
                    className={`${baseClass}__remove`}
                    icon="x"
                    onClick={handleFileRemoval}
                    round
                    tooltip={t('general:cancel')}
                  />
                  {renderSelectedFilePreview(fileSrc)}
                  <div className={`${baseClass}__file-adjustments`}>
                    {/* Custom id so this editor doesn't collide with the hidden auto `filename` field. */}
                    <TextInput
                      id="field-filemanager-filename"
                      label={t('upload:fileName')}
                      onChange={handleFileNameChange}
                      path="filename"
                      value={filename || value.name}
                    />
                    {(value.size || value.type) && (
                      <span className={`${baseClass}__selected-meta`}>
                        {[value.size ? formatFilesize(value.size) : null, value.type]
                          .filter(Boolean)
                          .join(' – ')}
                      </span>
                    )}
                  </div>
                </Fragment>
              )}
            </div>
          ) : null}
        </div>
      </div>
      {drawers}
    </div>
  )
}

