    font-weight: var(--text-body-medium-font-weight);
    line-height: var(--text-body-medium-line-height);
    color: var(--color-text-secondary);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .group-by-control__input {
    width: 100%;
  }

  .group-by-control__select-popup {
    width: 100%;
  }

  .group-by-control__select-trigger {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    min-height: var(--spacer-4);
    padding: 0 var(--spacer-1) 0 var(--spacer-2);
    background: var(--color-bg);
    border: var(--stroke-width-small) solid var(--color-border);
    border-radius: var(--button-radius);
    cursor: pointer;
    color: var(--color-text);
    font-size: var(--text-body-medium-font-size);
    font-weight: var(--text-body-medium-font-weight);
    line-height: var(--text-body-medium-line-height);
  }

  .group-by-control__select-trigger:hover:not(.group-by-control__select-trigger--disabled) {
    border-color: var(--color-border-hover);
  }

  .group-by-control__select-trigger--disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }

  .group-by-control__select-trigger svg {
    flex-shrink: 0;
    color: var(--color-text-secondary);
  }

  .group-by-control__select-value {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

elements/GroupBy/Popup.tsx:
'use client'
import React, { useCallback, useId } from 'react'

import type { ReducedField } from '../WhereBuilder/types.js'

import { ChevronIcon } from '../../icons/Chevron/index.js'
import { TrashIcon } from '../../icons/Trash/index.js'
import { XIcon } from '../../icons/X/index.js'
import { useTranslation } from '../../providers/Translation/index.js'
import { Button } from '../Button/index.js'
import { Popup, PopupList } from '../Popup/index.js'
import './Popup.css'

export type GroupByPopupProps = {
  /** Closes the parent popup. */
  readonly close: () => void
  /** The selectable, permission-filtered fields. */
  readonly filteredFields: ReducedField[]
  /** The currently selected field, if any. */
  readonly groupByField?: ReducedField
  /** The selected field path with any leading `-` stripped. */
  readonly groupByFieldName?: string
  /** Whether a field is currently selected. */
  readonly isActive: boolean
  /** Called with the next `groupBy` value (prefixed with `-` for descending). */
  readonly onChange: (groupBy: string) => void
  /** The current `groupBy` value (prefixed with `-` for descending). */
  readonly value: string
}

const baseClass = 'group-by-control'

export const GroupByPopup: React.FC<GroupByPopupProps> = ({
  close,
  filteredFields,
  groupByField,
  groupByFieldName,
  isActive,
  onChange,
  value,
}) => {
  const { t } = useTranslation()
  const generatedId = useId()
  const fieldTriggerId = `group-by-field-trigger-${generatedId}`
  const sortTriggerId = `group-by-sort-trigger-${generatedId}`

  const directionValue =
    !value || typeof value !== 'string' ? 'asc' : value.startsWith('-') ? 'desc' : 'asc'

  const handleFieldSelect = useCallback(
    (fieldPath: string) => {
      onChange(value?.startsWith('-') ? `-${fieldPath}` : fieldPath)
    },
    [onChange, value],
  )

  const handleClear = useCallback(() => {
    onChange('')
    close()
  }, [onChange, close])

  const handleDirectionSelect = useCallback(
    (direction: 'asc' | 'desc') => {
      if (!groupByFieldName) {
        return
      }
      onChange(direction === 'asc' ? groupByFieldName : `-${groupByFieldName}`)
    },
    [groupByFieldName, onChange],
  )

  return (
    <div className={`${baseClass}__content`}>
      <div className={`${baseClass}__header`}>
        <span className={`${baseClass}__title`}>{t('general:groupByLabel', { label: '' })}</span>
        <div className={`${baseClass}__header-actions`}>
          {isActive && (
            <Button
              aria-label={t('general:clear')}
              buttonStyle="ghost"
              icon={<TrashIcon />}
              onClick={handleClear}
              round
              size="medium"
            />
          )}
          <Button
            aria-label={t('general:close')}
            buttonStyle="ghost"
            icon={<XIcon size={24} />}
            onClick={close}
            round
            size="medium"
          />
        </div>
      </div>
      <div className={`${baseClass}__body`}>
        <div className={`${baseClass}__row`}>
          <label className={`${baseClass}__label`} htmlFor={fieldTriggerId}>
            {t('general:field')}
          </label>
          <div className={`${baseClass}__input`} data-popup-prevent-close>
            <Popup
              className={`${baseClass}__select-popup`}
              horizontalAlign="right"
              popupType="menu"
              render={({ close: closeFieldPopup }) => (
                <PopupList.RadioGroup>
                  {filteredFields.map((field, i) => (
                    <PopupList.RadioGroupItem
                      active={field.fieldPath === groupByFieldName}
                      key={i}
                      onClick={() => {
                        handleFieldSelect(field.fieldPath)
                        closeFieldPopup()
                      }}
                    >
                      {field.label}
                    </PopupList.RadioGroupItem>
                  ))}
                </PopupList.RadioGroup>
              )}
              renderButton={({ active, ...buttonProps }) => (
                <button
                  {...buttonProps}
                  aria-label={t('general:field')}
                  className={`${baseClass}__select-trigger`}
                  id={fieldTriggerId}
                  type="button"
                >
                  <span className={`${baseClass}__select-value`}>
                    {groupByField?.label || t('general:selectValue')}
                  </span>
                  <ChevronIcon direction={active ? 'up' : 'down'} size={16} />
                </button>
              )}
              verticalAlign="bottom"
            />
          </div>
        </div>
        <div className={`${baseClass}__row`}>
          <label className={`${baseClass}__label`} htmlFor={sortTriggerId}>
            {t('general:sort')}
          </label>
          <div className={`${baseClass}__input`} data-popup-prevent-close>
            <Popup
              className={`${baseClass}__select-popup`}
              disabled={!groupByFieldName}
              horizontalAlign="right"
              popupType="menu"
              render={({ close: closeSortPopup }) => (
                <PopupList.RadioGroup>
                  <PopupList.RadioGroupItem
                    active={directionValue === 'desc'}
                    onClick={() => {
                      handleDirectionSelect('desc')
                      closeSortPopup()
                    }}
                  >
                    {t('general:descending')}
                  </PopupList.RadioGroupItem>
                  <PopupList.RadioGroupItem
                    active={directionValue === 'asc'}
                    onClick={() => {
                      handleDirectionSelect('asc')
                      closeSortPopup()
                    }}
                  >
                    {t('general:ascending')}
                  </PopupList.RadioGroupItem>
                </PopupList.RadioGroup>
              )}
              renderButton={({ active, onClick, onKeyDown, ...ariaProps }) => (
                <button
                  {...ariaProps}
                  aria-disabled={!groupByFieldName}
                  aria-label={t('general:sort')}
                  className={[
                    `${baseClass}__select-trigger`,
                    !groupByFieldName && `${baseClass}__select-trigger--disabled`,
                  ]
                    .filter(Boolean)
                    .join(' ')}
                  id={sortTriggerId}
                  onClick={(event) => {
                    if (!groupByFieldName) {
                      event.preventDefault()
                      return
                    }
                    onClick(event)
                  }}
                  onKeyDown={(event) => {
                    if (!groupByFieldName) {
                      if (event.key === 'Enter' || event.key === ' ') {
                        event.preventDefault()
                      }
                      return
                    }
                    onKeyDown(event)
                  }}
                  type="button"
                >
                  <span className={`${baseClass}__select-value`}>
                    {directionValue === 'desc' ? t('general:descending') : t('general:ascending')}
                  </span>
                  <ChevronIcon direction={active ? 'up' : 'down'} size={16} />
                </button>
              )}
              size="small"
              verticalAlign="bottom"
            />
          </div>
        </div>
      </div>
    </div>
  )
}

elements/GroupBy/index.tsx:
'use client'
import type { ClientField, Field, SanitizedCollectionConfig } from 'payload'

import { isFieldDisabled } from 'payload/shared'
import React, { useMemo } from 'react'

import { ChevronIcon } from '../../icons/Chevron/index.js'
import { useAuth } from '../../providers/Auth/index.js'
import { useTranslation } from '../../providers/Translation/index.js'
import { reduceFieldsToOptions } from '../../utilities/reduceFieldsToOptions.js'
import { Button } from '../Button/index.js'
import { Popup } from '../Popup/index.js'
import { GroupByPopup } from './Popup.js'

export type GroupByButtonProps = {
  readonly collectionSlug: SanitizedCollectionConfig['slug']
  readonly fields: ClientField[]
  /** Called with the next `groupBy` value (prefixed with `-` for descending). */
  readonly onChange: (groupBy: string) => void
  /** The current `groupBy` value (prefixed with `-` for descending). */
  readonly value: string
}

const baseClass = 'group-by-control'

/**
 * Supported field types for group by functionality.
 */
const supportedFieldTypes: Field['type'][] = [
  'text',
  'textarea',
  'number',
  'select',
  'relationship',
  'date',
  'checkbox',
  'radio',
  'email',
  'upload',
]

export const GroupByButton: React.FC<GroupByButtonProps> = ({
  collectionSlug,
  fields,
  onChange,
  value,
}) => {
  const { i18n, t } = useTranslation()
  const { permissions } = useAuth()

  const groupByFieldName = value?.replace(/^-/, '')

  const fieldPermissions = permissions?.collections?.[collectionSlug]?.fields

  const reducedFields = useMemo(
    () =>
      reduceFieldsToOptions({
        fieldPermissions,
        fields,
        i18n,
      }),
    [fields, fieldPermissions, i18n],
  )

  const filteredFields = useMemo(
    () =>
      reducedFields.filter(
        (field) =>
          !isFieldDisabled(field.field, 'groupBy') &&
          field.fieldPath !== 'id' &&
          supportedFieldTypes.includes(field.field.type),
      ),
    [reducedFields],
  )

  const groupByField = reducedFields.find((field) => field.fieldPath === groupByFieldName)
  const isActive = Boolean(groupByFieldName && groupByField)

  if (filteredFields.length === 0) {
    return null
  }

  const triggerLabel = isActive
    ? t('general:groupByLabel', { label: groupByField?.label || '' })
    : t('general:groupByLabel', { label: '' })

  return (
    <Popup
      className={baseClass}
      horizontalAlign="right"
      popupAriaLabel={triggerLabel}
      popupType="dialog"
      portalClassName={`${baseClass}__popup`}
      render={({ close }) => (
        <GroupByPopup
          close={close}
          filteredFields={filteredFields}
          groupByField={groupByField}
          groupByFieldName={groupByFieldName}
          isActive={isActive}
          onChange={onChange}
          value={value}
        />
      )}
      renderButton={({ active, onClick, onKeyDown, ...ariaProps }) => (
        <Button
          buttonStyle="secondary"
          className={`${baseClass}__trigger`}
          extraButtonProps={{ onKeyDown }}
          icon={<ChevronIcon direction={active ? 'up' : 'down'} size={16} />}
          id="toggle-group-by"
          onClick={onClick}
          selected={active || isActive}
          size="medium"
          {...ariaProps}
        >
          {triggerLabel}
        </Button>
      )}
      size="large"
      theme="auto"
      verticalAlign="bottom"
    />
  )
}

