'use client'
import React from 'react'

import type { PathSegment } from '../../ColumnBrowser/types.js'

import { FolderIcon } from '../../../../icons/Folder/index.js'
import { ReplaceIcon } from '../../../../icons/Replace/index.js'
import { useTranslation } from '../../../../providers/Translation/index.js'
import { Button } from '../../../Button/index.js'
import { Chip } from '../../../Chip/index.js'
import { DialogFooter } from '../../../Dialog/index.js'
import './index.css'

const baseClass = 'hierarchy-modal-footer'

export type HierarchyModalFooterProps = {
  confirmLabel: string
  destinationPath?: PathSegment[]
  Icon?: React.ReactNode
  isBusy?: boolean
  isConfirmDisabled: boolean
  isMultiSelect: boolean
  onClear: () => void
  onConfirm: () => void
  onMoveToRoot?: () => void
  placeholderLabel: string
  previousPath?: PathSegment[]
  selectionCount: number
  selectionCountLabel: string
  showMoveToRoot?: boolean
}

const HierarchyPath: React.FC<{
  Icon?: React.ReactNode
  path: PathSegment[]
}> = ({ Icon, path }) => {
  const label = path.map((segment) => segment.title).join(' / ')

  return (
    <Chip aria-label={label} className={`${baseClass}__path`} icon={Icon ?? <FolderIcon />}>
      {label}
    </Chip>
  )
}

export const HierarchyModalFooter: React.FC<HierarchyModalFooterProps> = ({
  confirmLabel,
  destinationPath,
  Icon,
  isBusy = false,
  isConfirmDisabled,
  isMultiSelect,
  onClear,
  onConfirm,
  onMoveToRoot,
  placeholderLabel,
  previousPath,
  selectionCount,
  selectionCountLabel,
  showMoveToRoot,
}) => {
  const { t } = useTranslation()

  return (
    <DialogFooter>
      <div className={`${baseClass}__info`}>
        {isMultiSelect ? (
          <React.Fragment>
            <span className={`${baseClass}__secondary`}>{selectionCountLabel}</span>
            {selectionCount > 0 ? (
              <Button
                buttonStyle="primary-ghost"
                className={`${baseClass}__clear`}
                margin={false}
                onClick={onClear}
                size="medium"
              >
                {t('general:clear')}
              </Button>
            ) : null}
          </React.Fragment>
        ) : (
          <React.Fragment>
            {previousPath?.length ? (
              <React.Fragment>
                <HierarchyPath Icon={Icon} path={previousPath} />
                <span aria-hidden className={`${baseClass}__arrow`}>
                  <ReplaceIcon />
                </span>
              </React.Fragment>
            ) : null}
            {destinationPath?.length ? (
              <HierarchyPath Icon={Icon} path={destinationPath} />
            ) : (
              <span className={`${baseClass}__secondary`}>{placeholderLabel}</span>
            )}
          </React.Fragment>
        )}
      </div>
      <div className={`${baseClass}__actions`}>
        {showMoveToRoot && onMoveToRoot ? (
          <Button
            buttonStyle="secondary"
            disabled={isBusy}
            margin={false}
            onClick={onMoveToRoot}
            size="medium"
          >
            {t('hierarchy:moveToRoot')}
          </Button>
        ) : null}
        <Button
          disabled={isBusy || isConfirmDisabled}
          margin={false}
          onClick={onConfirm}
          size="medium"
        >
          {confirmLabel}
        </Button>
      </div>
    </DialogFooter>
  )
}

elements/Hierarchy/Modal/fetchAncestorPa:
import { formatAdminURL } from 'payload/shared'
import * as qs from 'qs-esm'

import type { PathSegment } from '../ColumnBrowser/types.js'

type FetchAncestorPathArgs = {
  api: string
  collectionSlug: string
  itemId: number | string
  parentFieldName: string
  serverURL: string
  useAsTitle: string
}

export type AncestorPathResult = {
  ancestorIds: (number | string)[]
  path: PathSegment[]
}

const MAX_HIERARCHY_DEPTH = 20

/**
 * Fetches the ancestor path for an item using a single API call with depth.
 * Returns the ancestor IDs used to expand the browser and a titled path for the footer.
 */
export async function fetchAncestorPath({
  api,
  collectionSlug,
  itemId,
  parentFieldName,
  serverURL,
  useAsTitle,
}: FetchAncestorPathArgs): Promise<AncestorPathResult> {
  const queryString = qs.stringify(
    {
      depth: MAX_HIERARCHY_DEPTH,
      limit: 1,
      select: { [parentFieldName]: true, [useAsTitle]: true },
      where: { id: { equals: itemId } },
    },
    { addQueryPrefix: true },
  )

  const url = formatAdminURL({
    apiRoute: api,
    path: `/${collectionSlug}${queryString}`,
    serverURL,
  })

  const response = await fetch(url, { credentials: 'include' })

  if (!response.ok) {
    return { ancestorIds: [], path: [] }
  }

  const data = await response.json()
  const doc = data.docs?.[0]

  if (!doc) {
    return { ancestorIds: [], path: [] }
  }

  const path: PathSegment[] = [toPathSegment({ id: itemId, doc, useAsTitle })]
  let current = doc[parentFieldName] as null | number | Record<string, unknown> | string

  while (current !== null && current !== undefined) {
    const parentId = typeof current === 'object' ? current.id : current

    if (parentId !== null && parentId !== undefined) {
      path.unshift(
        toPathSegment({
          id: parentId as number | string,
          doc: typeof current === 'object' ? current : undefined,
          useAsTitle,
        }),
      )
    }

    current =
      typeof current === 'object'
        ? (current[parentFieldName] as null | number | Record<string, unknown> | string)
        : null
  }

  return {
    ancestorIds: path.slice(0, -1).map((segment) => segment.id),
    path,
  }
}

function toPathSegment({
  id,
  doc,
  useAsTitle,
}: {
  doc?: Record<string, unknown>
  id: number | string
  useAsTitle: string
}): PathSegment {
  const title = doc?.[useAsTitle]

  return {
    id,
    title: typeof title === 'number' || typeof title === 'string' ? String(title) : String(id),
  }
}

