import type { SidebarTabServerProps, Where } from 'payload'

import { getTranslation } from '@payloadcms/translations'
import { DEFAULT_HIERARCHY_TREE_LIMIT, getInitialTreeData } from 'payload'
import { PREFERENCE_KEYS } from 'payload/shared'
import React from 'react'

// eslint-disable-next-line payload/no-imports-from-exports-dir -- Server component must reference exports dir for proper client boundary
import { HierarchySidebarTab } from '../../../exports/client/index.js'
import { TagIcon } from '../../../icons/Tag/index.js'
import { RenderServerComponent } from '../../RenderServerComponent/index.js'

export type HierarchySidebarTabServerProps = {
  hierarchyCollectionSlug: string
} & SidebarTabServerProps

export const HierarchySidebarTabServer: React.FC<HierarchySidebarTabServerProps> = async ({
  hierarchyCollectionSlug,
  i18n,
  payload,
  req,
  searchParams,
  user,
}) => {
  if (!user) {
    return null
  }

  let initialData = null
  let initialExpandedNodes: (number | string)[] = []
  let initialSelectedFilters: string[] = []
  let selectedNodeId: null | string = null
  let parentFieldName = 'parent'
  let treeLimit: number | undefined
  let typeFieldName: string | undefined
  let useAsTitle: string | undefined
  let collectionSpecificOptions: { label: string; value: string }[] = []
  let baseFilter: null | Where = null

  // Get collection config and render icon (outside try block - doesn't need async)
  const collectionConfig = payload.collections[hierarchyCollectionSlug]?.config
  const hierarchyConfig =
    collectionConfig?.hierarchy && typeof collectionConfig.hierarchy === 'object'
      ? collectionConfig.hierarchy
      : undefined

  const IconComponent = hierarchyConfig?.admin?.components?.SmallIcon
  const icon = IconComponent ? (
    RenderServerComponent({
      clientProps: { size: 16 },
      Component: IconComponent,
      importMap: payload.importMap,
      key: `hierarchy-sidebar-icon-${hierarchyCollectionSlug}`,
    })
  ) : (
    <TagIcon size={16} />
  )

  try {
    // Get parentFieldName from config first (needed for URL parsing)
    parentFieldName = hierarchyConfig?.parentFieldName ?? 'parent'

    // Get selected node from URL (?<parentFieldName>=<id>)
    const selectedNodeParam = searchParams?.[parentFieldName]
    selectedNodeId = selectedNodeParam ? String(selectedNodeParam) : null

    // STEP 1: Load user's expanded node preferences
    const preferenceKey = `${PREFERENCE_KEYS.HIERARCHY_TREE}-${hierarchyCollectionSlug}`

    const { docs: preferenceDocs } = await payload.find({
      collection: 'payload-preferences',
      limit: 1,
      overrideAccess: false,
      user,
      where: {
        and: [
          { key: { equals: preferenceKey } },
          { 'user.value': { equals: user.id } },
          { 'user.relationTo': { equals: user.collection } },
        ],
      },
    })

    const preferences = preferenceDocs[0]

    if (preferences?.value?.expandedNodes) {
      initialExpandedNodes = preferences.value.expandedNodes
    }

    if (preferences?.value?.selectedFilters) {
      initialSelectedFilters = preferences.value.selectedFilters
    }

    // STEP 2: Get remaining config values
    treeLimit = hierarchyConfig?.admin?.treeLimit
    typeFieldName =
      hierarchyConfig?.collectionSpecific && typeof hierarchyConfig.collectionSpecific === 'object'
        ? hierarchyConfig.collectionSpecific.fieldName
        : undefined
    useAsTitle = collectionConfig?.admin?.useAsTitle

    // STEP 2.5: Build collection-specific options from related collections
    if (hierarchyConfig.collectionSpecific && hierarchyConfig?.relatedCollections) {
      collectionSpecificOptions = Object.keys(hierarchyConfig.relatedCollections)
        .map((slug) => {
          const relatedConfig = payload.collections[slug]?.config
          const label = relatedConfig?.labels?.plural ?? slug

          return {
            label: getTranslation(label, i18n),
            value: slug,
          }
        })
        .sort((a, b) => a.label.localeCompare(b.label))
    }

    // Track the immediate parent of the selected node (for ensuring siblings are loaded)
    let selectedNodeParentId: null | number | string = null

    // If there's a selected node, ensure its ancestor chain is expanded
    if (selectedNodeId) {
      // Walk up the parent chain to root
      const ancestorIds: (number | string)[] = []
      let currentNodeId: null | number | string = selectedNodeId
      let isFirstIteration = true

      while (currentNodeId) {
        try {
          const node = await payload.findByID({
            id: currentNodeId,
            collection: hierarchyCollectionSlug,
            depth: 0,
            overrideAccess: false,
            user,
          })

          const parentId = node?.[parentFieldName]

          // Capture the immediate parent of the selected node
          if (isFirstIteration) {
            selectedNodeParentId = parentId ?? null
            isFirstIteration = false
          }

          if (parentId) {
            ancestorIds.push(parentId)
            currentNodeId = parentId
          } else {
            currentNodeId = null
          }
        } catch {
          // Node not found or access denied
          break
        }
      }

      // Merge ancestor IDs with existing expanded nodes
      const expandedSet = new Set(initialExpandedNodes)
      ancestorIds.forEach((id) => expandedSet.add(id))
      // Include the selected node itself so its own children are loaded.
      expandedSet.add(selectedNodeId)
      initialExpandedNodes = Array.from(expandedSet)
    }

    const baseFilterFn =
      collectionConfig?.admin?.baseFilter ?? collectionConfig?.admin?.baseListFilter
    if (baseFilterFn && req) {
      baseFilter =
        (await baseFilterFn({ limit: DEFAULT_HIERARCHY_TREE_LIMIT, page: 1, req, sort: 'id' })) ??
        null
    }

    initialData = await getInitialTreeData({
      baseFilter,
      collectionSlug: hierarchyCollectionSlug,
      expandedNodeIds: initialExpandedNodes,
      ...(initialSelectedFilters.length > 0 && { filterByCollections: initialSelectedFilters }),
      ...(treeLimit !== undefined && { limit: treeLimit }),
      payload,
      selectedNodeId,
      selectedNodeParentId,
      user: req.user,
    })
  } catch (error) {
    payload.logger.warn({
      err: error,
      msg: `Failed to fetch hierarchy data for ${hierarchyCollectionSlug}`,
    })
    // Fall back to client-side fetching if server fetch fails
  }

  return (
    <HierarchySidebarTab
      baseFilter={baseFilter}
      collectionSpecificOptions={collectionSpecificOptions}
      hierarchyCollectionSlug={hierarchyCollectionSlug}
      icon={icon}
      initialData={initialData}
      initialExpandedNodes={initialExpandedNodes}
      initialSelectedFilters={initialSelectedFilters}
      parentFieldName={parentFieldName}
      selectedNodeId={selectedNodeId}
      treeLimit={treeLimit}
      typeFieldName={typeFieldName}
      useAsTitle={useAsTitle}
    />
  )
}

'use client'

import type { SidebarTabClientProps } from 'payload'

import { formatAdminURL } from 'payload/shared'
import * as qs from 'qs-esm'
import React, { useCallback, useEffect, useRef, useState } from 'react'

import type { HierarchyInitialData } from './types.js'

import { useConfig } from '../../../providers/Config/index.js'
import { useHierarchy } from '../../../providers/Hierarchy/index.js'
import { useRouter, useSearchParams } from '../../../providers/RouterAdapter/index.js'
import { useRouteTransition } from '../../../providers/RouteTransition/index.js'
import { useSidebarTabs } from '../../../providers/SidebarTabs/index.js'
import { HydrateHierarchyProvider } from '../HydrateProvider/index.js'
import { HierarchySearch } from '../Search/index.js'
import { HierarchyTree } from './index.js'

export const HierarchySidebarTab: React.FC<
  {
    baseFilter?: Record<string, unknown>
    collectionSpecificOptions?: { label: string; value: string }[]
    hierarchyCollectionSlug: string
    icon?: React.ReactNode
    initialData?: HierarchyInitialData | null
    initialExpandedNodes?: (number | string)[]
    initialSelectedFilters?: string[]
    parentFieldName?: string
    selectedNodeId?: null | string
    treeLimit?: number
    typeFieldName?: string
    useAsTitle?: string
  } & SidebarTabClientProps
> = ({
  baseFilter,
  collectionSpecificOptions,
  hierarchyCollectionSlug,
  icon,
  initialData,
  initialExpandedNodes,
  initialSelectedFilters,
  parentFieldName,
  selectedNodeId: selectedNodeIdFromServer,
  treeLimit,
  typeFieldName,
  useAsTitle,
}) => {
  const router = useRouter()
  const searchParams = useSearchParams()
  const { startRouteTransition } = useRouteTransition()
  const {
    config: {
      routes: { admin: adminRoute },
    },
  } = useConfig()
  const [isSearchActive, setIsSearchActive] = useState(false)
  const [selectedFilters, setSelectedFiltersLocal] = useState<string[]>(
    initialSelectedFilters ?? [],
  )
  const { setSelectedFilters: setSelectedFiltersContext, treeRefreshKeys } = useHierarchy()
  const sidebarTabs = useSidebarTabs()

  const resolvedParentFieldName = parentFieldName ?? 'parent'
  const currentParentParam = searchParams.get(resolvedParentFieldName)

  // When refreshTree(slug) is called from the list view (e.g. after mutations), reload this tab.
  // Always reload regardless of active state so inactive tabs are fresh when switched to.
  // The render-tab server function runs with a fresh request that lacks the client's URL query,
  // so forward the current selected parent id — otherwise the reload can't tell which node is
  // being viewed and rebuilds the tree from preference state.
  const tabSlug = `hierarchy-${hierarchyCollectionSlug}`
  const isActiveTab = sidebarTabs?.activeTabSlug === tabSlug
  const treeRefreshKey = treeRefreshKeys.get(hierarchyCollectionSlug) ?? 0
  const prevTreeRefreshKeyRef = useRef(treeRefreshKey)
  useEffect(() => {
    if (prevTreeRefreshKeyRef.current !== treeRefreshKey) {
      prevTreeRefreshKeyRef.current = treeRefreshKey
      // Only forward the selected parent id when this tab is active. currentParentParam
      // reflects the global URL search params, so an inactive tab could otherwise pick up
      // another hierarchy collection's value if they share the same parentFieldName.
      sidebarTabs?.reloadTabContent(tabSlug, {
        searchParams:
          isActiveTab && currentParentParam
            ? { [resolvedParentFieldName]: currentParentParam }
            : undefined,
      })
    }
  }, [
    treeRefreshKey,
    sidebarTabs,
    tabSlug,
    isActiveTab,
    currentParentParam,
    resolvedParentFieldName,
  ])

  // Only highlight selected node when this tab is active
  const selectedNodeId = isActiveTab
    ? (currentParentParam ?? selectedNodeIdFromServer ?? undefined)
    : undefined

  const baseFilterKey = baseFilter ? JSON.stringify(baseFilter) : ''

  const handleFilterChange = useCallback(
    (filters: string[]) => {
      setSelectedFiltersLocal(filters)
      setSelectedFiltersContext(filters)
    },
    [setSelectedFiltersContext],
  )

  const handleNavigateToParent = useCallback(
    ({ id }: { id: number | string }) => {
      const url = formatAdminURL({
        adminRoute,
        path: `/collections/${hierarchyCollectionSlug}${qs.stringify(
          { [resolvedParentFieldName]: id, view: 'hierarchy' },
          { addQueryPrefix: true },
        )}`,
      })
      startRouteTransition(() => {
        router.push(url)
        router.refresh()
      })
    },
    [adminRoute, hierarchyCollectionSlug, resolvedParentFieldName, router, startRouteTransition],
  )
  return (
    <>
      <HydrateHierarchyProvider
        baseFilter={baseFilter}
        collectionSlug={hierarchyCollectionSlug}
        expandedNodes={initialExpandedNodes}
        parentFieldName={parentFieldName}
        selectedFilters={initialSelectedFilters}
        treeData={initialData}
        treeLimit={treeLimit}
        typeFieldName={typeFieldName}
      />
      <div className="hierarchy-sidebar-tab">
        <HierarchySearch
          collectionSlug={hierarchyCollectionSlug}
          collectionSpecificOptions={collectionSpecificOptions}
          isActive={isSearchActive}
          onActiveChange={setIsSearchActive}
          onFilterChange={handleFilterChange}
          onSelect={handleNavigateToParent}
          selectedFilters={selectedFilters}
        />
        {!isSearchActive && (
          <HierarchyTree
            baseFilter={baseFilter}
            collectionSlug={hierarchyCollectionSlug}
            filterByCollections={selectedFilters.length > 0 ? selectedFilters : undefined}
            icon={icon}
            initialData={initialData}
            initialExpandedNodes={initialExpandedNodes}
            key={`${hierarchyCollectionSlug}-${baseFilterKey}`}
            onNodeClick={handleNavigateToParent}
            selectedNodeId={selectedNodeId}
            useAsTitle={useAsTitle}
          />
        )}
      </div>
    </>
  )
}

