'use client'

import type { PublishButtonClientProps } from 'payload'

import { getTranslation } from '@payloadcms/translations'
import { formatAdminURL, hasAutosaveEnabled, hasLocalizeStatusEnabled } from 'payload/shared'
import * as qs from 'qs-esm'
import React, { useCallback, useState } from 'react'
import { toast } from 'sonner'

import { useForm, useFormModified } from '../../forms/Form/context.js'
import { FormSubmit } from '../../forms/Submit/index.js'
import { useHotkey } from '../../hooks/useHotkey.js'
import { useConfig } from '../../providers/Config/index.js'
import { useDocumentInfo } from '../../providers/DocumentInfo/index.js'
import { useEditDepth } from '../../providers/EditDepth/index.js'
import { useLocale } from '../../providers/Locale/index.js'
import { useOperation } from '../../providers/Operation/index.js'
import { useTranslation } from '../../providers/Translation/index.js'
import { useUploadEdits } from '../../providers/UploadEdits/index.js'
import { traverseForLocalizedFields } from '../../utilities/traverseForLocalizedFields.js'
import { PopupList } from '../Popup/index.js'
import { FieldErrorsToast } from '../Toasts/fieldErrors.js'
import { validateDocumentLocales } from './validateAllLocales.js'
import './index.css'

export function PublishButton({
  label: labelProp,
}: { label?: string } & PublishButtonClientProps = {}) {
  const {
    id,
    collectionSlug,
    globalSlug,
    hasPublishedDoc,
    hasPublishPermission,
    setHasPublishedDoc,
    setMostRecentVersionIsAutosaved,
    setUnpublishedVersionCount,
    unpublishedVersionCount,
    uploadStatus,
  } = useDocumentInfo()

  const { config, getEntityConfig } = useConfig()
  const { getData, submit } = useForm()
  const { uploadEdits } = useUploadEdits()
  const modified = useFormModified()
  const editDepth = useEditDepth()
  const locale = useLocale()
  const localeCode = locale?.code
  const {
    blocksMap,
    localization,
    routes: { api },
  } = config

  const { i18n, t } = useTranslation()
  const label = labelProp || t('version:publishChanges')
  const shortLabel = labelProp || t('version:publish')

  const entityConfig = React.useMemo(() => {
    if (collectionSlug) {
      return getEntityConfig({ collectionSlug })
    }

    if (globalSlug) {
      return getEntityConfig({ globalSlug })
    }
  }, [collectionSlug, globalSlug, getEntityConfig])

  const hasNewerVersions = unpublishedVersionCount > 0

  const canPublish =
    hasPublishPermission &&
    (modified || hasNewerVersions || !hasPublishedDoc) &&
    uploadStatus !== 'uploading'

  const [isValidatingLocales, setIsValidatingLocales] = useState(false)

  const hasLocalizedFields = React.useMemo(
    () =>
      Boolean(
        entityConfig?.fields &&
          traverseForLocalizedFields({
            blocksMap,
            fields: entityConfig.fields,
          }),
      ),
    [blocksMap, entityConfig?.fields],
  )

  const isSpecificLocalePublishEnabled = localization && hasLocalizedFields && hasPublishPermission

  const operation = useOperation()

  const disabled = operation === 'update' && !modified

  // If autosave is enabled the modified will always be true so only conditionally check on modified state
  const hasAutosave = hasAutosaveEnabled(entityConfig)

  const saveDraft = useCallback(async () => {
    if (disabled) {
      return
    }

    const params = qs.stringify(
      {
        depth: 0,
        draft: true,
        'fallback-locale': 'null',
        locale: localeCode,
        uploadEdits: uploadEdits || undefined,
      },
      { addQueryPrefix: true },
    )

    let action
    let method = 'POST'

    if (collectionSlug) {
      action = formatAdminURL({
        apiRoute: api,
        path: `/${collectionSlug}${id ? `/${id}` : ''}${params}`,
      })
      if (id) {
        method = 'PATCH'
      }
    }

    if (globalSlug) {
      action = formatAdminURL({
        apiRoute: api,
        path: `/globals/${globalSlug}${params}`,
      })
    }

    await submit({
      action,
      method,
      overrides: {
        _status: 'draft',
      },
      skipValidation: true,
    })
  }, [disabled, localeCode, collectionSlug, globalSlug, submit, api, id, uploadEdits])

  useHotkey({ cmdCtrlKey: true, editDepth, keyCodes: ['s'] }, (e) => {
    e.preventDefault()
    e.stopPropagation()

    if (saveDraft && hasAutosave) {
      void saveDraft()
    }
  })

  const localizeStatusEnabled = hasLocalizeStatusEnabled(entityConfig)

  const publish = useCallback(async () => {
    if (uploadStatus === 'uploading') {
      return
    }

    if (localization && hasLocalizedFields) {
      setIsValidatingLocales(true)
      let validation

      try {
        const encodedID = id === undefined ? '' : `/${encodeURIComponent(String(id))}`
        let validationPath: `/${string}`

        if (globalSlug) {
          validationPath = `/globals/${encodeURIComponent(globalSlug)}/validate`
        } else if (collectionSlug) {
          validationPath = `/${encodeURIComponent(collectionSlug)}${encodedID}/validate`
        } else {
          throw new Error('Document validation requires a collection or global slug.')
        }

        validation = await validateDocumentLocales({
          activeLocale: localeCode,
          blocksMap,
          data: { ...getData(), _status: 'published' },
          endpoint: formatAdminURL({ apiRoute: api, path: validationPath }),
          fields: entityConfig?.fields ?? [],
          locales: localization.locales.map(({ code }) => code),
        })
      } catch {
        toast.error(t('error:unknown'))
        return
      } finally {
        setIsValidatingLocales(false)
      }

      if (!validation.valid) {
        const introMessage = t('error:followingFieldsInvalid', { count: validation.errors.length })
        const fieldList = validation.errors
          .map(
            (error) =>
              `${error.locale ? `[${error.locale}] ` : ''}${
                error.label ? getTranslation(error.label, i18n) : error.path
              }`,
          )
          .join(', ')

        toast.error(<FieldErrorsToast errorMessage={`${introMessage} ${fieldList}`} />)
        return
      }
    }

    const params = qs.stringify(
      {
        depth: 0,
        locale: localeCode,
        uploadEdits: uploadEdits || undefined,
        ...(localizeStatusEnabled && { publishAllLocales: true }),
      },
      { addQueryPrefix: true },
    )

    const action = formatAdminURL({
      apiRoute: api,
      path: `${
        globalSlug ? `/globals/${globalSlug}` : `/${collectionSlug}${id ? `/${id}` : ''}`
      }${params}` as `/${string}`,
    })

    const result = await submit({
      action,
      overrides: {
        _status: 'published',
      },
    })

    if (result) {
      setUnpublishedVersionCount(0)
      setMostRecentVersionIsAutosaved(false)
      setHasPublishedDoc(true)
    }
  }, [
    localeCode,
    localizeStatusEnabled,
    api,
    blocksMap,
    collectionSlug,
    entityConfig?.fields,
    getData,
    globalSlug,
    hasLocalizedFields,
    id,
    localization,
    i18n,
    setHasPublishedDoc,
    submit,
    setUnpublishedVersionCount,
    t,
    uploadStatus,
    setMostRecentVersionIsAutosaved,
    uploadEdits,
  ])

  const publishLocale = useCallback(
    async (locale) => {
      if (uploadStatus === 'uploading') {
        return
      }

      const params = qs.stringify(
        {
          depth: 0,
          locale,
          uploadEdits: uploadEdits || undefined,
        },
        { addQueryPrefix: true },
      )

      const pathSegment = globalSlug
        ? `/globals/${globalSlug}`
        : `/${collectionSlug}${id ? `/${id}` : ''}`
      const action = formatAdminURL({
        apiRoute: api,
        path: `${pathSegment}${params}` as `/${string}`,
      })

      const result = await submit({
        action,
        overrides: {
          _status: 'published',
        },
      })

      if (result) {
        setUnpublishedVersionCount(0)
        setMostRecentVersionIsAutosaved(false)
        setHasPublishedDoc(true)
      }
    },
    [
      api,
      collectionSlug,
      globalSlug,
      id,
      setHasPublishedDoc,
      setMostRecentVersionIsAutosaved,
      setUnpublishedVersionCount,
      submit,
      uploadStatus,
      uploadEdits,
    ],
  )

  const activeLocale =
    localization &&
    localization?.locales.find((locale) =>
      typeof locale === 'string' ? locale === localeCode : locale.code === localeCode,
    )

  const activeLocaleLabel = activeLocale && getTranslation(activeLocale.label, i18n)

  if (!hasPublishPermission) {
    return null
  }

  return (
    <React.Fragment>
      <FormSubmit
        buttonId="action-save"
        disabled={!canPublish || isValidatingLocales}
        loading={isValidatingLocales}
        onClick={isSpecificLocalePublishEnabled ? () => publishLocale(activeLocale.code) : publish}
        size="medium"
        SubMenuPopupContent={
          isSpecificLocalePublishEnabled
            ? () => (
                <PopupList.ButtonGroup>
                  <PopupList.Button id="publish-all-locales" onClick={publish}>
                    {t('version:publishAllLocales')}
                  </PopupList.Button>
                </PopupList.ButtonGroup>
              )
            : undefined
        }
        type="button"
      >
        {isSpecificLocalePublishEnabled ? (
          t('version:publishIn', { locale: activeLocaleLabel })
        ) : (
          <React.Fragment>
            <span className="publish-button__label--full">{label}</span>
            <span className="publish-button__label--short">{shortLabel}</span>
          </React.Fragment>
        )}
      </FormSubmit>
    </React.Fragment>
  )
}

