'use client'

import type { BrowserAutoComplete } from 'payload'

import React, { useCallback } from 'react'

import { SearchIcon } from '../../../icons/Search/index.js'
import { XIcon } from '../../../icons/X/index.js'
import { useTranslation } from '../../../providers/Translation/index.js'
import { Button } from '../../Button/index.js'
import './index.css'

const baseClass = 'search-input'

type SearchInputProps = {
  'aria-describedby'?: string
  'aria-label'?: string
  autoComplete?: BrowserAutoComplete
  className?: string
  disabled?: boolean
  id?: string
  onChange: (value: string) => void
  onClear?: () => void
  onSearch?: (value: string) => void
  placeholder?: string
  value: string
}

export const SearchInput: React.FC<SearchInputProps> = ({
  id,
  'aria-describedby': ariaDescribedBy,
  'aria-label': ariaLabel,
  autoComplete,
  className,
  disabled,
  onChange,
  onClear,
  onSearch,
  placeholder,
  value,
}) => {
  const { t } = useTranslation()

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === 'Enter' && !e.nativeEvent.isComposing && value.length > 0) {
        onSearch(value)
      }
    },
    [value, onSearch],
  )

  return (
    <div className={[baseClass, className].filter(Boolean).join(' ')}>
      <SearchIcon />
      <input
        aria-describedby={ariaDescribedBy}
        aria-label={ariaLabel ?? placeholder}
        autoComplete={autoComplete}
        className={`${baseClass}__input`}
        disabled={disabled}
        id={id}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={onSearch ? handleKeyDown : undefined}
        placeholder={placeholder}
        type="text"
        value={value}
      />
      {onClear && value.length > 0 && (
        <Button
          aria-label={t('general:clearSearch')}
          buttonStyle="ghost"
          className={`${baseClass}__clear`}
          icon={<XIcon size={16} />}
          margin={false}
          onClick={onClear}
          round
          size="medium"
        />
      )}
    </div>
  )
}

