      /* stylelint-disable-next-line plugin/no-subpixel-values -- TODO: pre-existing; revisit this sub-pixel value */
      top: calc(50% + 0.5px);
      /* stylelint-disable-next-line plugin/no-subpixel-values -- TODO: pre-existing; revisit this sub-pixel value */
      left: calc(100% - 0.5px);
      transform: translateY(calc(1 * var(--caret-width) / 2 + var(--tooltip-caret-y)))
