'use client'

import type { UnpublishButtonClientProps } from 'payload'

import { useModal } from '@faceless-ui/modal'
import { getTranslation } from '@payloadcms/translations'
import { formatAdminURL, hasLocalizeStatusEnabled } from 'payload/shared'
import * as qs from 'qs-esm'
import React, { useCallback, useState } from 'react'
import { toast } from 'sonner'

import { useForm } from '../../forms/Form/context.js'
import { useConfig } from '../../providers/Config/index.js'
import { useDocumentInfo } from '../../providers/DocumentInfo/index.js'
import { useLocale } from '../../providers/Locale/index.js'
import { useTranslation } from '../../providers/Translation/index.js'
import { requests } from '../../utilities/api.js'
import { ConfirmationModal } from '../ConfirmationModal/index.js'
import { PopupList } from '../Popup/index.js'
export function UnpublishButton({
  label: labelProp,
}: { label?: string } & UnpublishButtonClientProps = {}) {
  const {
    id,
    collectionSlug,
    data: dataFromProps,
    globalSlug,
    hasPublishedDoc,
    hasPublishPermission,
    incrementVersionCount,
    isTrashed,
    setHasPublishedDoc,
    setMostRecentVersionIsAutosaved,
    setUnpublishedVersionCount,
  } = useDocumentInfo()
  const { toggleModal } = useModal()

  const { config, getEntityConfig } = useConfig()
  const { reset: resetForm } = useForm()
  const locale = useLocale()
  const localeCode = locale?.code
  const localeLabel = locale?.label
  const [unpublishAll, setUnpublishAll] = useState(false)
  const unPublishModalSlug = `confirm-un-publish-${id}`

  const {
    routes: { api },
    serverURL,
  } = config

  const { i18n, t } = useTranslation()

  const entityConfig = React.useMemo(() => {
    if (collectionSlug) {
      return getEntityConfig({ collectionSlug })
    }

    if (globalSlug) {
      return getEntityConfig({ globalSlug })
    }
  }, [collectionSlug, globalSlug, getEntityConfig])

  const unpublish = useCallback(
    (unpublishAll?: boolean) => {
      void (async () => {
        let url
        let method

        const queryString = qs.stringify(
          {
            depth: 0,
            'fallback-locale': 'null',
            locale: unpublishAll ? undefined : localeCode,
            unpublishAllLocales: unpublishAll,
          },
          { addQueryPrefix: true },
        )

        if (collectionSlug) {
          url = formatAdminURL({
            apiRoute: api,
            path: `/${collectionSlug}/${id}${queryString}`,
            serverURL,
          })
          method = 'patch'
        }

        if (globalSlug) {
          url = formatAdminURL({
            apiRoute: api,
            path: `/globals/${globalSlug}${queryString}`,
            serverURL,
          })
          method = 'post'
        }

        try {
          const res = await requests[method](url, {
            body: JSON.stringify({ _status: 'draft' }),
            headers: {
              'Accept-Language': i18n.language,
              'Content-Type': 'application/json',
            },
          })

          if (res.status === 200) {
            void resetForm({
              ...(dataFromProps || {}),
              _status: 'draft',
            })

            toast.success(t('version:unpublishedSuccessfully'))
            if (!unpublishAll) {
              incrementVersionCount()
            }
            setUnpublishedVersionCount(1)
            setMostRecentVersionIsAutosaved(false)
            setHasPublishedDoc(false)
          } else {
            try {
              const json = await res.json()
              if (json.errors?.[0]?.message) {
                toast.error(json.errors[0].message)
              } else if (json.error) {
                toast.error(json.error)
              } else {
                toast.error(t('error:unPublishingDocument'))
              }
            } catch {
              toast.error(t('error:unPublishingDocument'))
            }
          }
        } catch {
          toast.error(t('error:unPublishingDocument'))
        }
      })().catch(() => {
        toast.error(t('error:unPublishingDocument'))
      })
    },
    [
      dataFromProps,
      resetForm,
      collectionSlug,
      globalSlug,
      serverURL,
      api,
      localeCode,
      id,
      i18n.language,
      incrementVersionCount,
      setHasPublishedDoc,
      setMostRecentVersionIsAutosaved,
      setUnpublishedVersionCount,
      t,
    ],
  )

  const drafts = entityConfig?.versions?.drafts
  const hasDraftsEnabled = typeof drafts === 'object' && drafts !== null

  const canUnpublish = React.useMemo(() => {
    return hasDraftsEnabled && hasPublishPermission && hasPublishedDoc && !isTrashed
  }, [hasPublishPermission, hasPublishedDoc, isTrashed, hasDraftsEnabled])

  const canUnpublishCurrentLocale = React.useMemo(() => {
    if (!canUnpublish) {
      return false
    }

    return Boolean(entityConfig && hasLocalizeStatusEnabled(entityConfig))
  }, [canUnpublish, entityConfig])

  const label = getTranslation(localeLabel, i18n)

  if (!canUnpublish) {
    return null
  }

  return (
    <React.Fragment>
      <PopupList.Button
        id="action-unpublish"
        onClick={() => {
          setUnpublishAll(true)
          toggleModal(unPublishModalSlug)
        }}
      >
        {labelProp || t('version:unpublish')}
      </PopupList.Button>
      {canUnpublishCurrentLocale && (
        <PopupList.Button
          id="action-unpublish-locale"
          onClick={() => {
            setUnpublishAll(false)
            toggleModal(unPublishModalSlug)
          }}
        >
          {labelProp ? `${labelProp} [${label}]` : t('version:unpublishIn', { locale: label })}
        </PopupList.Button>
      )}
      <ConfirmationModal
        body={
          !unpublishAll
            ? t('version:aboutToUnpublishIn', { locale: label })
            : t('version:aboutToUnpublish')
        }
        confirmingLabel={t('version:unpublishing')}
        heading={t('version:confirmUnpublish')}
        modalSlug={unPublishModalSlug}
        onConfirm={() => unpublish(unpublishAll)}
      />
    </React.Fragment>
  )
}

elements/UnpublishMany/DrawerContent.tsx:
import type { Where } from 'payload'

import { getTranslation } from '@payloadcms/translations'
import { combineWhereConstraints, formatAdminURL, mergeListSearchAndWhere } from 'payload/shared'
import * as qs from 'qs-esm'
import React, { useCallback } from 'react'
import { toast } from 'sonner'

import type { UnpublishManyProps } from './index.js'

import { useConfig } from '../../providers/Config/index.js'
import { useLocale } from '../../providers/Locale/index.js'
import { useRouteCache } from '../../providers/RouteCache/index.js'
import { useRouter, useSearchParams } from '../../providers/RouterAdapter/index.js'
import { useTranslation } from '../../providers/Translation/index.js'
import { requests } from '../../utilities/api.js'
import { parseSearchParams } from '../../utilities/parseSearchParams.js'
import { ConfirmationModal } from '../ConfirmationModal/index.js'

type UnpublishManyDrawerContentProps = {
  collection: UnpublishManyProps['collection']
  drawerSlug: string
  ids: (number | string)[]
  onSuccess?: () => void
  selectAll: boolean
  where?: Where
}

export function UnpublishManyDrawerContent(props: UnpublishManyDrawerContentProps) {
  const {
    collection,
    collection: { slug, labels: { plural, singular } } = {},
    drawerSlug,
    ids,
    onSuccess,
    selectAll,
    where,
  } = props

  const {
    config: {
      routes: { api },
    },
  } = useConfig()
  const currentLocale = useLocale()
  const locale = currentLocale?.code
  const { i18n, t } = useTranslation()
  const searchParams = useSearchParams()
  const router = useRouter()
  const { clearRouteCache } = useRouteCache()
  const addDefaultError = useCallback(() => {
    toast.error(t('error:unknown'))
  }, [t])

  const queryString = React.useMemo((): string => {
    const whereConstraints: Where[] = [
      {
        _status: {
          not_equals: 'draft',
        },
      },
    ]

    if (where) {
      whereConstraints.push(where)
    }

    const queryWithSearch = mergeListSearchAndWhere({
      collectionConfig: collection,
      search: searchParams.get('search'),
    })

    if (queryWithSearch) {
      whereConstraints.push(queryWithSearch)
    }

    if (!selectAll) {
      // If we're not selecting all, we need to select specific docs
      whereConstraints.push({
        id: {
          in: ids || [],
        },
      })
    }

    return qs.stringify(
      {
        locale,
        select: {},
        where: combineWhereConstraints(whereConstraints),
      },
      { addQueryPrefix: true },
    )
  }, [collection, searchParams, selectAll, ids, locale, where])

  const handleUnpublish = useCallback(async () => {
    const url = formatAdminURL({
      apiRoute: api,
      path: `/${slug}${queryString}`,
    })
    await requests
      .patch(url, {
        body: JSON.stringify({
          _status: 'draft',
        }),
        headers: {
          'Accept-Language': i18n.language,
          'Content-Type': 'application/json',
        },
      })
      .then(async (res) => {
        try {
          const json = await res.json()

          const deletedDocs = json?.docs.length || 0
          const successLabel = deletedDocs > 1 ? plural : singular

          if (res.status < 400 || deletedDocs > 0) {
            toast.success(
              t('general:updatedCountSuccessfully', {
                count: deletedDocs,
                label: getTranslation(successLabel, i18n),
              }),
            )

            if (json?.errors.length > 0) {
              toast.error(json.message, {
                description: json.errors.map((error) => error.message).join('\n'),
              })
            }

            router.replace(
              qs.stringify(
                {
                  ...parseSearchParams(searchParams),
                  page: selectAll ? '1' : undefined,
                },
                { addQueryPrefix: true },
              ),
            )

            clearRouteCache()

            if (typeof onSuccess === 'function') {
              onSuccess()
            }

            return null
          }

          if (json.errors) {
            json.errors.forEach((error) => toast.error(error.message))
          } else {
            addDefaultError()
          }
          return false
        } catch (_err) {
          return addDefaultError()
        }
      })
  }, [
    api,
    slug,
    queryString,
    i18n,
    plural,
    singular,
    t,
    router,
    searchParams,
    selectAll,
    clearRouteCache,
    addDefaultError,
    onSuccess,
  ])

  return (
    <ConfirmationModal
      body={t('version:aboutToUnpublishSelection', { label: getTranslation(plural, i18n) })}
      confirmingLabel={t('version:unpublishing')}
      heading={t('version:confirmUnpublish')}
      modalSlug={drawerSlug}
      onConfirm={handleUnpublish}
    />
  )
}

