@layer payload-default {
  .condition {
    display: contents;

    .btn {
      vertical-align: middle;
      margin: 0;
    }
  }

  /* Flatten wrap and inputs — all 5 cells (__join, __field, __operator, __value, __actions)
     become direct items of the parent or-filters grid, no subgrid needed. */
  .condition__wrap,
  .condition__inputs {
    display: contents;
  }

  .condition__join-label {
    display: block;
    color: var(--color-text);
  }

  /* The and/or join dropdown is compact (24px tall) per the design. */
  .condition__join .rs__control {
    min-height: var(--spacer-4);
    padding-block: 0;
    padding-inline: calc(var(--spacer-1) * 1.5) var(--spacer-4);
    text-transform: lowercase;
  }

  .condition__join-menu {
    text-transform: lowercase;
  }

  /* Center the indicators within the compact control. The base styles
     absolutely position them with a fixed 32px height tuned for the default
     control, so pin to the control interior and center instead. */
  .condition__join .rs__indicators {
    inset-block: 0;
    min-height: 0;
    align-items: center;
  }

  /* display:contents makes the three input divs participate directly in the parent grid */
  .condition__inputs > div {
    min-width: 0;
  }

  .condition__field .field-label {
    padding-bottom: 0;
  }

  .condition__actions {
    display: flex;
    gap: var(--spacer-2);
  }

  /* stylelint-disable-next-line plugin/no-max-width-media-query -- TODO: pre-existing; migrate to a mobile-first min-width query */
  @media (max-width: 768px) {
    .condition {
      display: block;
    }

    .condition__wrap {
      margin-top: var(--spacer-3);
      display: grid;
      grid-template-columns: 1fr auto;
      grid-template-areas:
        'join actions'
        'field field'
        'operator operator'
        'value value';
      gap: var(--spacer-2);
      align-items: start;
    }

    .condition__inputs {
      display: contents;
    }

    .condition__join {
      grid-area: join;
    }

    .condition__join .rs__control {
      min-width: calc(var(--spacer-4) * 3);
      /* width: fit-content; */
    }

    .condition__field {
      grid-area: field;
    }

    .condition__operator {
      grid-area: operator;
    }

    .condition__value {
      grid-area: value;
    }

    .condition__inputs > div {
      flex-basis: auto;
      width: 100%;
    }

    .condition__actions {
      grid-area: actions;
      align-self: center;
    }
  }
}

