@layer payload-default {
  .checkbox {
    position: relative;
  }

  .field-type.checkbox:has(+ .checkbox) {
    margin-bottom: var(--spacer-2);
  }

  .checkbox-input {
    display: flex;
  }

  .checkbox-input__wrap {
    position: relative;
    display: inline-flex;
    align-items: flex-start;
    gap: var(--spacer-2);
    width: 100%;
  }

  /* Positioning shell only. The border, fill and focus ring all live on
     `__visuals`, which is a sibling of the input so every visual state can be
     driven from the input's own pseudo-classes. */
  .checkbox-input__input {
    position: relative;
    display: inline-block;
    flex-shrink: 0;
    width: var(--spacer-3);
    height: var(--spacer-3);
    margin-block: var(--spacer-1);

    user-select: none;
  }

  /* Kept in the accessibility tree and hit-testable, but invisible */
  .checkbox-input__control {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    padding: 0;
    border-radius: 0;
    outline: none;
    opacity: 0;
  }

  .checkbox-input__visuals {
    --checkbox-bg: var(--color-bg-secondary);
    --checkbox-border-color: var(--special-border-translucent-strong);
    --checkbox-focus-ring-color: transparent;
    --checkbox-mark-color: var(--color-icon);
    --checkbox-mark-halo-color: transparent;
    --checkbox-duration: 100ms;
    --checkbox-easing: cubic-bezier(0.645, 0.045, 0.355, 1);

    position: absolute;
    inset: 0;
    display: inline-grid;
    place-content: center;
    border: var(--stroke-width-small) solid var(--checkbox-border-color);
    border-radius: var(--radius-small);
    outline: var(--stroke-width-small) solid var(--checkbox-focus-ring-color);
    outline-offset: var(--stroke-width-small);
    background: var(--checkbox-bg);
    pointer-events: none;
  }

  .checkbox-input__check,
  .checkbox-input__mixed {
    display: none;
    width: var(--spacer-3);
    height: var(--spacer-3);
  }

  .checkbox-input__mark,
  .checkbox-input__mark-halo {
    stroke-linecap: round;
    stroke-linejoin: round;

    /* The dash pattern is longer than either path, so offsetting by its length
       hides the mark entirely and animating back to 0 draws it in. */
    stroke-dasharray: 12;
    stroke-dashoffset: 0;
  }

  .checkbox-input__mark {
    stroke: var(--checkbox-mark-color);
    stroke-width: 1.5;
  }

  .checkbox-input__mark-halo {
    stroke: var(--checkbox-mark-halo-color);
    stroke-width: 4;
  }

  .checkbox-input__control:hover + .checkbox-input__visuals {
    --checkbox-bg: var(--color-bg-secondary-hover);
  }

  .checkbox-input__control:focus-visible + .checkbox-input__visuals {
    --checkbox-focus-ring-color: var(--accessibility-focus-color);
  }

  .checkbox-input__control:active + .checkbox-input__visuals {
    --checkbox-bg: var(--color-bg-secondary-pressed);
  }

  .checkbox-input__control:disabled + .checkbox-input__visuals {
    --checkbox-bg: transparent;
    --checkbox-border-color: var(--color-border-disabled);
    --checkbox-mark-color: var(--color-icon-ondisabled);
  }

  .checkbox-input__control:disabled:checked + .checkbox-input__visuals,
  .checkbox-input__control:disabled:indeterminate + .checkbox-input__visuals {
    --checkbox-mark-color: var(--color-icon-disabled);
  }

  .checkbox-input__control:disabled:not(.checkbox-input__control--muted):checked
    + .checkbox-input__visuals,
  .checkbox-input__control:disabled:not(.checkbox-input__control--muted):indeterminate
    + .checkbox-input__visuals {
    --checkbox-bg: var(--color-bg-disabled);
    --checkbox-border-color: transparent;
    --checkbox-mark-color: var(--color-icon-ondisabled);
  }

  .checkbox-input__control:not(.checkbox-input__control--muted, :disabled)
    + .checkbox-input__visuals {
    --checkbox-mark-color: var(--color-icon-onbrand);
    --checkbox-mark-halo-color: var(--special-border-translucent);
  }

  .checkbox-input__control:not(.checkbox-input__control--muted, :disabled):checked
    + .checkbox-input__visuals,
  .checkbox-input__control:not(.checkbox-input__control--muted, :disabled):indeterminate
    + .checkbox-input__visuals {
    --checkbox-bg: var(--color-bg-brand);
    --checkbox-border-color: var(--special-border-translucent);

    transition: background var(--checkbox-duration) var(--checkbox-easing);
  }

  .checkbox-input__control:not(.checkbox-input__control--muted, :disabled):checked:hover
    + .checkbox-input__visuals,
  .checkbox-input__control:not(.checkbox-input__control--muted, :disabled):indeterminate:hover
    + .checkbox-input__visuals {
    --checkbox-border-color: var(--special-border-translucent-strong);
  }

  .checkbox-input__control:not(.checkbox-input__control--muted, :disabled):checked:active
    + .checkbox-input__visuals,
  .checkbox-input__control:not(.checkbox-input__control--muted, :disabled):indeterminate:active
    + .checkbox-input__visuals {
    --checkbox-bg: var(--color-bg-brand-hover);
  }

  .checkbox-input__control.checkbox-input__control--muted:checked + .checkbox-input__visuals,
  .checkbox-input__control.checkbox-input__control--muted:indeterminate + .checkbox-input__visuals {
    --checkbox-bg: var(--field-color-toggle-bg-checked);
    --checkbox-border-color: var(--field-color-toggle-border-checked);
    --checkbox-mark-color: var(--field-color-toggle-icon);

    transition: background var(--checkbox-duration) var(--checkbox-easing);
  }

  .checkbox-input__control.checkbox-input__control--muted:checked:hover + .checkbox-input__visuals,
  .checkbox-input__control.checkbox-input__control--muted:indeterminate:hover
    + .checkbox-input__visuals {
    --checkbox-border-color: var(--special-border-translucent-strong);
  }

  .checkbox-input__control.checkbox-input__control--muted:checked:active + .checkbox-input__visuals,
  .checkbox-input__control.checkbox-input__control--muted:indeterminate:active
    + .checkbox-input__visuals {
    --checkbox-bg: var(--color-bg-brand-hover);
  }

  .checkbox-input__control:indeterminate + .checkbox-input__visuals .checkbox-input__mixed {
    display: block;
  }

  .checkbox-input__control:checked:not(:indeterminate)
    + .checkbox-input__visuals
    .checkbox-input__check {
    display: block;
  }

  .checkbox-input--changed .checkbox-input__mark,
  .checkbox-input--changed .checkbox-input__mark-halo {
    animation: payload-checkbox-mark-draw var(--checkbox-duration) var(--checkbox-easing) forwards;
  }

  @keyframes payload-checkbox-mark-draw {
    from {
      stroke-dashoffset: 12;
    }

    to {
      stroke-dashoffset: 0;
    }
  }

  .checkbox-input label.field-label {
    margin-block-start: var(--spacer-1);
  }

  .checkbox > .field-description {
    padding-inline-start: var(--spacer-4);
  }

  .checkbox-input:not(.checkbox-input--read-only),
  .checkbox-input:not(.checkbox-input--read-only) label,
  .checkbox-input:not(.checkbox-input--read-only) input {
    cursor: pointer;
  }

  .checkbox-input--read-only label.field-label:not(.unstyled) {
    color: var(--field-color-text-disabled);
  }

  .checkbox-input--has-tooltip {
    position: relative;
    width: max-content;
    max-width: 100%;
  }

  /* Allow Wrap */
  .checkbox-input__tooltip {
    left: 0;
    width: max-content;
    max-width: 280px;
    white-space: normal;
    text-align: start;
  }

  /* Center the caret on the checkbox box itself (0.5rem from the row's
     left edge = center of the 1rem-wide checkbox input). */
  .checkbox-input__tooltip.tooltip--caret-left .tooltip__caret {
    left: 0.5rem;
    transform: translateX(-50%);
  }

  .checkbox-input__tooltip.tooltip--caret-left.tooltip--position-bottom .tooltip__caret {
    transform: translateX(-50%) rotate(180deg);
  }

  .checkbox.error .checkbox-input__visuals {
    --checkbox-border-color: var(--field-color-border-error);
  }

  .checkbox.error .checkbox-input__control:checked + .checkbox-input__visuals,
  .checkbox.error .checkbox-input__control:indeterminate + .checkbox-input__visuals {
    --checkbox-bg: var(--field-color-error-bg);
    --checkbox-border-color: var(--field-color-border-error);
  }
}

