  'M24 24H0V0H24V24ZM18 3.5C16.067 3.5 14.5 5.067 14.5 7C14.5 8.933 16.067 10.5 18 10.5C19.933 10.5 21.5 8.933 21.5 7C21.5 5.067 19.933 3.5 18 3.5Z'

export const ScheduleIcon: React.FC<{
